func TestParseLimitsMissingHeaders(t *testing.T) {
	l := parseLimits(http.Header{})
	if l.LimitRequests != -1 || l.RemainingTokens != -1 || l.RetryAfter != 0 {
		t.Errorf("missing headers should give -1/0, got %+v", l)
	}
}

