import math
docs = {"c0": ["attention","attention","model"], "c1": ["model","training","data"], "c2": ["speech","model"]}
N = len(docs); avg = sum(map(len, docs.values()))/N; k1, b = 1.2, 0.75
df = {}
for d in docs.values():
    for t in set(d): df[t] = df.get(t,0)+1
idf = lambda t: math.log(1 + (N - df.get(t,0) + 0.5)/(df.get(t,0) + 0.5))
def score(q, d):
    return sum(idf(t) * d.count(t)*(k1+1) / (d.count(t) + k1*(1-b+b*len(d)/avg)) for t in set(q))
def norm(q, d): return score(q,d) / sum(idf(t)*(k1+1) for t in set(q))
for q in [["attention"], ["model"], ["speech","model"], ["speech","dijkstra"]]:
    print(q, {k: round(score(q,d),6) for k,d in docs.items()}, "norm", {k: round(norm(q,d),6) for k,d in docs.items()})
EOF

