func (r *Reservation) Cancel() {
	r.settle(float64(r.tokens), 1)
}

func (r *Reservation) settle(tokensBack, requestsBack float64) {
	l := r.l
	l.mu.Lock()
	defer l.mu.Unlock()
	if r.done {
