		p.lim.PauseFor(rl.RetryAfter)
		res.Cancel() // refused calls did not run
	case err == nil:
		p.lim.Observe(resp.Limits)
		res.Finish(resp.TokensIn + resp.TokensOut)
	default:
		if resp != nil {
			p.lim.Observe(resp.Limits)
		}
		res.Finish(0) // it was sent; actual tokens unknown
	}
