python3 -I - <<'EOF'
from pathlib import Path
p = Path("internal/pipeline/pipeline.go"); s = p.read_text()
start = s.index("// settle tells the limiter what happened.")
end = s.index("// timeModel adds this attempt's time inside the model call.")
new = '''// settle tells the limiter what happened: first our own bookkeeping
// (refund or settle the reservation), then the provider's headers, which
// describe the state after this call and so must have the last word.
// (Applying headers first once let a refund undo them: a 429 said "0
// requests left today", the refund added one back, and the next person
// got "busy" instead of the day-gone passages.) Limits are only believed
// when headers actually arrived; a 429's retry hint pauses everyone.
func (p *Pipeline) settle(res *traffic.Reservation, resp *llm.Response, err error) {
	var rl *llm.RateLimitError
	switch {
	case errors.As(err, &rl):
		res.Cancel() // refused calls did not run
		if rl.Header != nil {
			p.lim.Observe(rl.Limits)
		}
		if p.cfg.Retry.UseHint { // the naive policy ignores the hint entirely
			p.lim.PauseFor(rl.RetryAfter)
		}
	case err == nil:
		res.Finish(resp.TokensIn + resp.TokensOut)
		if resp.Header != nil {
			p.lim.Observe(resp.Limits)
		}
	default:
		res.Finish(0) // it was sent; actual tokens unknown
		if resp != nil && resp.Header != nil {
			p.lim.Observe(resp.Limits)
		}
	}
}

'''
p.write_text(s[:start] + new + s[end:])
t = Path("internal/pipeline/pipeline_test.go"); u = t.read_text()
u += '''
// Regression (daily-exhausted run): a 429 said "0 requests left today",
// then refunding the refused call added one back, so the next person got
// L2 "busy" instead of L3 passages.
func TestDayGoneLearnedFrom429LeadsToPassages(t *testing.T) {
	cfg := standin.Default()
	cfg.StartRPD = 0
	cfg.FirstTokenMS, cfg.RefusalMS = []float64{1}, 0
	srv := httptest.NewServer(standin.New(cfg))
	defer srv.Close()
	p, _ := newPipeline(t, llm.NewHTTP(srv.URL, ""), traffic.GroqFree)

	first := ask(p, question)
	if first.Status != "rate_limited" || first.N429 != 1 {
		t.Fatalf("first reply %+v", first)
	}
	if second := ask(p, question); second.Level != traffic.L3RetrievalOnly {
		t.Errorf("second reply: level %v (%s), want L3 passages", second.Level, second.Detail)
	}
}
'''
t.write_text(u)
EOF
gofmt -w internal/pipeline && go test -count=1 -race ./internal/pipeline/ 2>&1 | tail -2; git stash -q -- internal/pipeline/pipeline.go && go test -count=1 -run DayGoneLearned ./internal/pipeline/ 2>&1 | grep -E '^(---|ok|FAIL)|want L3' | head -3; git stash pop -q; git status --short

