#!/bin/sh
# Block the commit unless gofmt, go vet and all tests pass.
exec make check

// Package llm is the model client. One HTTP implementation talks to any
// OpenAI-compatible streaming endpoint, so Groq and the stand-in are
// indistinguishable to the pipeline (DESIGN.md §4).
package llm

import (
	"context"
	"net/http"
	"time"
)

// Message is one chat turn.
type Message struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

// Request is everything the pipeline controls about a model call.
type Request struct {
	Model           string
	Messages        []Message
	MaxTokens       int
	Temperature     float64
	ReasoningEffort string // "low", "medium", "high"; empty = provider default

	// FirstTokenTimeout cancels the call if no content arrives in time.
	// Zero means no separate first-token deadline (ctx still applies).
	FirstTokenTimeout time.Duration
}

// Response is a finished call. Times are wall-clock so the recorder can
// split latency into waiting (before Sent) and working (Sent..Done).
type Response struct {
	Text      string
	TokensIn  int
	TokensOut int // includes reasoning tokens: they count toward limits

	Sent       time.Time // request written
	FirstToken time.Time // first non-empty content piece
	Done       time.Time // stream finished

	Limits RateLimits
	Header http.Header // raw response headers, kept for the probe
}

// RateLimits holds the provider's view of our remaining budget.
// Per Groq docs: *Requests* fields refer to the per-day limit, *Tokens*
// fields to the per-minute limit. -1 / 0 mean the header was absent.
type RateLimits struct {
	LimitRequests     int
	RemainingRequests int
	ResetRequests     time.Duration
	LimitTokens       int
	RemainingTokens   int
	ResetTokens       time.Duration
	RetryAfter        time.Duration // only set on 429
}

// Client is the one interface the pipeline sees.
type Client interface {
	Complete(ctx context.Context, req Request) (*Response, error)
}

package llm

import (
	"fmt"
	"net/http"
	"time"
)

// The retry policy decides by error type, so each failure mode gets its own.

// RateLimitError is a 429. RetryAfter is the provider's hint (0 if absent).
type RateLimitError struct {
	RetryAfter time.Duration
	Limits     RateLimits
	Header     http.Header
	Body       string
}

func (e *RateLimitError) Error() string {
	return fmt.Sprintf("rate limited (retry after %s): %s", e.RetryAfter, e.Body)
}

// ServerError is a 5xx, or Groq's 498 (flex capacity), or an error event
// sent inside an otherwise-200 stream.
type ServerError struct {
	Status int
	Body   string
}

func (e *ServerError) Error() string { return fmt.Sprintf("server error %d: %s", e.Status, e.Body) }

// ClientError is any other 4xx: our request is wrong, retrying cannot help.
type ClientError struct {
	Status int
	Body   string
}

func (e *ClientError) Error() string { return fmt.Sprintf("client error %d: %s", e.Status, e.Body) }

// TimeoutError means a deadline passed. Phase is "first_token" if nothing
// had arrived yet, "total" if the answer had started streaming.
type TimeoutError struct {
	Phase string
}

func (e *TimeoutError) Error() string { return "timeout before " + e.Phase }

// ConnError is a dropped or broken connection: dial failure, reset, or a
// stream that ended without its terminator. Partial holds text received.
type ConnError struct {
	Partial string
	Err     error
}

func (e *ConnError) Error() string { return "connection: " + e.Err.Error() }
func (e *ConnError) Unwrap() error { return e.Err }

