// Package corpus loads the parsed papers and cuts them into citable chunks.
package corpus

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Block is one run of text on one page under one heading, as written by
// scripts/parse.py.
type Block struct {
	Page    int    `json:"page"`
	Section string `json:"section"` // "3.2.1", "A.1", or "" for named parts
	Title   string `json:"title"`   // "Scaled Dot-Product Attention", "Abstract"
	Text    string `json:"text"`
}

// Doc is one parsed paper.
type Doc struct {
	Paper   string  `json:"paper"`
	Version int     `json:"version"`
	Blocks  []Block `json:"blocks"`
}

// Chunk is the unit of retrieval and citation.
type Chunk struct {
	ID        string // "1706.03762v7#12", unique across the corpus
	Paper     string
	Version   int
	Section   string
	Title     string
	PageStart int
	PageEnd   int
	Text      string
}

// Citation renders the reference shown to the person, e.g.
// "[1706.03762v7, §3.2.1, p.4]" or "[2410.00037v1, Abstract, pp.1-2]".
func (c Chunk) Citation() string {
	where := c.Title
	if c.Section != "" {
		where = "§" + c.Section
	}
	pages := fmt.Sprintf("p.%d", c.PageStart)
	if c.PageEnd != c.PageStart {
		pages = fmt.Sprintf("pp.%d-%d", c.PageStart, c.PageEnd)
	}
	return fmt.Sprintf("[%sv%d, %s, %s]", c.Paper, c.Version, where, pages)
}

// LoadDir reads every *.json doc in dir, sorted by file name so chunk IDs
// are stable between runs.
func LoadDir(dir string) ([]Doc, error) {
	paths, err := filepath.Glob(filepath.Join(dir, "*.json"))
	if err != nil {
		return nil, err
	}
	if len(paths) == 0 {
		return nil, fmt.Errorf("no parsed papers in %s", dir)
	}
	sort.Strings(paths)
	docs := make([]Doc, 0, len(paths))
	for _, p := range paths {
		b, err := os.ReadFile(p)
		if err != nil {
			return nil, err
		}
		var d Doc
		if err := json.Unmarshal(b, &d); err != nil {
			return nil, fmt.Errorf("%s: %w", p, err)
		}
		docs = append(docs, d)
	}
	return docs, nil
}

// Build cuts every doc into chunks of at most size words, consecutive
// chunks sharing overlap words. A chunk never crosses a section boundary,
// so each chunk has exactly one section to cite; it may span pages.
func Build(docs []Doc, size, overlap int) ([]Chunk, error) {
	if size <= 0 || overlap < 0 || overlap >= size {
		return nil, fmt.Errorf("need size > overlap >= 0, got size=%d overlap=%d", size, overlap)
	}
	var out []Chunk
	for _, d := range docs {
		n := 0 // per-paper chunk counter for IDs
		for _, run := range sectionRuns(d.Blocks) {
			for _, w := range windows(len(run.words), size, overlap) {
				out = append(out, Chunk{
					ID:        fmt.Sprintf("%sv%d#%d", d.Paper, d.Version, n),
					Paper:     d.Paper,
					Version:   d.Version,
					Section:   run.section,
					Title:     run.title,
					PageStart: run.pages[w[0]],
					PageEnd:   run.pages[w[1]-1],
					Text:      strings.Join(run.words[w[0]:w[1]], " "),
				})
				n++
			}
		}
	}
	return out, nil
}

// run is the words of consecutive blocks under one heading, with the page
// each word came from.
type run struct {
	section, title string
	words          []string
	pages          []int
}

// sectionRuns merges consecutive blocks with the same heading.
func sectionRuns(blocks []Block) []run {
	var runs []run
	for _, b := range blocks {
		if len(runs) == 0 || runs[len(runs)-1].section != b.Section || runs[len(runs)-1].title != b.Title {
			runs = append(runs, run{section: b.Section, title: b.Title})
		}
		r := &runs[len(runs)-1]
		for _, w := range strings.Fields(b.Text) {
			r.words = append(r.words, w)
			r.pages = append(r.pages, b.Page)
		}
	}
	return runs
}

// windows returns [start, end) word ranges of at most size, stepping by
// size-overlap, with the last window ending exactly at n.
func windows(n, size, overlap int) [][2]int {
	var out [][2]int
	for start := 0; start < n; start += size - overlap {
		end := min(start+size, n)
		out = append(out, [2]int{start, end})
		if end == n {
			break
		}
	}
	return out
}

package corpus

import (
	"fmt"
	"reflect"
	"strings"
	"testing"
)

func words(prefix string, n int) string {
	ws := make([]string, n)
	for i := range ws {
		ws[i] = fmt.Sprintf("%s%d", prefix, i)
	}
	return strings.Join(ws, " ")
}

func TestCitation(t *testing.T) {
	tests := []struct {
		c    Chunk
		want string
	}{
		{Chunk{Paper: "1706.03762", Version: 7, Section: "3.2.1", PageStart: 4, PageEnd: 4}, "[1706.03762v7, §3.2.1, p.4]"},
		{Chunk{Paper: "2410.00037", Version: 1, Title: "Abstract", PageStart: 1, PageEnd: 2}, "[2410.00037v1, Abstract, pp.1-2]"},
	}
	for _, tt := range tests {
		if got := tt.c.Citation(); got != tt.want {
			t.Errorf("got %q, want %q", got, tt.want)
		}
	}
}

func TestWindows(t *testing.T) {
	tests := []struct {
		n, size, overlap int
		want             [][2]int
	}{
		{0, 10, 2, nil},
		{5, 10, 2, [][2]int{{0, 5}}},
		{10, 10, 2, [][2]int{{0, 10}}},
		{11, 10, 2, [][2]int{{0, 10}, {8, 11}}},
		{20, 10, 0, [][2]int{{0, 10}, {10, 20}}},
	}
	for _, tt := range tests {
		if got := windows(tt.n, tt.size, tt.overlap); !reflect.DeepEqual(got, tt.want) {
			t.Errorf("windows(%d,%d,%d) = %v, want %v", tt.n, tt.size, tt.overlap, got, tt.want)
		}
	}
}

func TestBuildRespectsSectionsAndTracksPages(t *testing.T) {
	doc := Doc{Paper: "1234.5678", Version: 2, Blocks: []Block{
		{Page: 1, Section: "1", Title: "Intro", Text: words("a", 6)},
		{Page: 2, Section: "1", Title: "Intro", Text: words("b", 6)}, // same section, next page
		{Page: 2, Section: "2", Title: "Method", Text: words("c", 3)},
	}}
	chunks, err := Build([]Doc{doc}, 8, 2)
	if err != nil {
		t.Fatal(err)
	}
	// Section 1 has 12 words: windows [0,8) and [6,12). Section 2: [0,3).
	type got struct {
		id, sec   string
		from, to  int
		nWords    int
		firstWord string
	}
	var gs []got
	for _, c := range chunks {
		f := strings.Fields(c.Text)
		gs = append(gs, got{c.ID, c.Section, c.PageStart, c.PageEnd, len(f), f[0]})
	}
	want := []got{
		{"1234.5678v2#0", "1", 1, 2, 8, "a0"},
		{"1234.5678v2#1", "1", 1, 2, 6, "a0"[:0] + "b0"}, // starts at word 6 = b0, ends on page 2
		{"1234.5678v2#2", "2", 2, 2, 3, "c0"},
	}
	// Second window starts at word 6 (b0) so it lies entirely on page 2.
	want[1].from = 2
	if !reflect.DeepEqual(gs, want) {
		t.Errorf("got  %+v\nwant %+v", gs, want)
	}
}

func TestBuildRejectsBadSizes(t *testing.T) {
	for _, c := range [][2]int{{0, 0}, {10, 10}, {10, -1}} {
		if _, err := Build(nil, c[0], c[1]); err == nil {
			t.Errorf("size=%d overlap=%d should fail", c[0], c[1])
		}
	}
}

// TestRealCorpus checks the committed parsed papers chunk sanely.
func TestRealCorpus(t *testing.T) {
	docs, err := LoadDir("../../data/parsed")
	if err != nil {
		t.Fatal(err)
	}
	if len(docs) != 3 {
		t.Fatalf("want 3 papers, got %d", len(docs))
	}
	for _, size := range []int{150, 300} {
		chunks, err := Build(docs, size, size/5)
		if err != nil {
			t.Fatal(err)
		}
		ids := map[string]bool{}
		for _, c := range chunks {
			n := len(strings.Fields(c.Text))
			if n == 0 || n > size || ids[c.ID] || c.PageStart > c.PageEnd {
				t.Fatalf("bad chunk %s: words=%d dup=%v pages=%d-%d", c.ID, n, ids[c.ID], c.PageStart, c.PageEnd)
			}
			ids[c.ID] = true
		}
		t.Logf("size %d: %d chunks", size, len(chunks))
	}
}

