// Package standin is a fake model provider we control: slow, slower under
// load, failing on purpose, refusing at limits, streaming in pieces.
// It speaks the same wire format as Groq so llm.HTTPClient cannot tell.
package standin

import (
	"encoding/json"
	"os"
)

// Config is every knob of the stand-in. Default() fills it from the probe;
// a JSON file can override any field for a scenario.
type Config struct {
	Source string // which probe run the numbers came from

	// Latency (milliseconds).
	FirstTokenMS      []float64 // idle first-token samples, resampled per call
	InputMSPerToken   float64   // extra first-token delay per prompt token
	OutputMSPerToken  float64   // streaming speed after the first token
	LoadMSPerInFlight float64   // extra first-token delay per other request in flight
	RefusalMS         float64   // how long a 429 takes to come back

	// Token accounting (no real tokenizer: chars / CharsPerToken).
	PromptOverheadTokens int
	CharsPerToken        float64
	ReasoningTokens      int // hidden tokens spent before any content

	// Failures, as probabilities per request. Not calibrated: the probe
	// saw none in 61 calls, so scenarios set these.
	ServerErrorRate float64
	DropRate        float64 // connection cut partway through the stream

	// Limits. Zero disables a limit. Start* set the daily buckets' initial
	// level (-1 = full), for the "daily budget exhausted" scenario.
	RPM, TPM, RPD, TPD int
	MaxInFlight        int
	StartRPD, StartTPD int

	Seed uint64
}

// Default returns the stand-in calibrated from probe run 20261112T054119Z
// (results/probe/README.md).
func Default() Config {
	return Config{
		Source:            "probe 20261112T054119Z",
		FirstTokenMS:      []float64{220, 285, 317, 348, 358, 405, 408, 416, 420, 432},
		InputMSPerToken:   0.05,
		OutputMSPerToken:  0.8,
		LoadMSPerInFlight: 24,
		RefusalMS:         130,

		PromptOverheadTokens: 72,
		CharsPerToken:        5,
		ReasoningTokens:      20,

		RPM: 30, TPM: 8000, RPD: 1000, TPD: 200000,
		StartRPD: -1, StartTPD: -1,
		Seed: 1,
	}
}

// Load reads a JSON file of overrides on top of Default().
func Load(path string) (Config, error) {
	cfg := Default()
	b, err := os.ReadFile(path)
	if err != nil {
		return cfg, err
	}
	err = json.Unmarshal(b, &cfg)
	return cfg, err
}

package standin

import (
	"math"
	"time"
)

// bucket is the provider-side limit: capacity refilled evenly over a
// period, which is how Groq's TPM and RPD behaved in the probe.
// A nil bucket means "no limit". Callers hold the server lock.
type bucket struct {
	capacity float64
	perSec   float64 // refill rate
	level    float64
	last     time.Time
}

// newBucket returns nil when capacity <= 0. start < 0 means full.
func newBucket(capacity int, period time.Duration, start int, now time.Time) *bucket {
	if capacity <= 0 {
		return nil
	}
	level := float64(capacity)
	if start >= 0 {
		level = float64(start)
	}
	return &bucket{capacity: float64(capacity), perSec: float64(capacity) / period.Seconds(), level: level, last: now}
}

func (b *bucket) refill(now time.Time) {
	if dt := now.Sub(b.last).Seconds(); dt > 0 {
		b.level = math.Min(b.capacity, b.level+dt*b.perSec)
		b.last = now
	}
}

// wait is how long until n units are available (0 = available now).
func (b *bucket) wait(n float64, now time.Time) time.Duration {
	if b == nil {
		return 0
	}
	b.refill(now)
	if b.level >= n {
		return 0
	}
	return time.Duration((n - b.level) / b.perSec * float64(time.Second))
}

// charge removes n units; the level may go negative (output tokens are
// only known after the fact).
func (b *bucket) charge(n float64, now time.Time) {
	if b == nil {
		return
	}
	b.refill(now)
	b.level -= n
}

// remaining is the whole units left, floored at 0.
func (b *bucket) remaining(now time.Time) int {
	b.refill(now)
	return int(math.Max(0, math.Floor(b.level)))
}

// untilFull is what Groq reports as x-ratelimit-reset-*.
func (b *bucket) untilFull(now time.Time) time.Duration {
	b.refill(now)
	return time.Duration((b.capacity - b.level) / b.perSec * float64(time.Second))
}

package standin

import (
	"fmt"
	"regexp"
	"strings"
)

// The pipeline renders each retrieved chunk on its own line as
// "[<chunk id>] <text>". The stand-in answers by quoting the first chunk it
// sees, so its answers pass verification and load runs measure traffic,
// not redraft storms. With no chunks it refuses, as a real model should.
var chunkLine = regexp.MustCompile(`^\[([^\]\s]+#\d+)\]\s+(.+)$`)

const quoteWords = 12

func answer(msgs []message) string {
	for i := len(msgs) - 1; i >= 0; i-- {
		if msgs[i].Role != "user" {
			continue
		}
		for _, line := range strings.Split(msgs[i].Content, "\n") {
			m := chunkLine.FindStringSubmatch(strings.TrimSpace(line))
			if m == nil {
				continue
			}
			words := strings.Fields(m[2])
			if len(words) > quoteWords {
				words = words[:quoteWords]
			}
			return fmt.Sprintf("The papers state: %q [%s].", strings.Join(words, " "), m[1])
		}
		break // only the last user message counts
	}
	return "The papers do not say."
}

package standin

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"math/rand/v2"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Server implements POST /chat/completions (streaming only).
type Server struct {
	cfg Config
	now func() time.Time // replaced in tests

	mu       sync.Mutex
	rng      *rand.Rand
	inFlight int
	rpm      *bucket
	tpm      *bucket
	rpd      *bucket
	tpd      *bucket
}

func New(cfg Config) *Server {
	return newWithClock(cfg, time.Now)
}

func newWithClock(cfg Config, now func() time.Time) *Server {
	t := now()
	return &Server{
		cfg: cfg,
		now: now,
		rng: rand.New(rand.NewPCG(cfg.Seed, cfg.Seed)),
		rpm: newBucket(cfg.RPM, time.Minute, -1, t),
		tpm: newBucket(cfg.TPM, time.Minute, -1, t),
		rpd: newBucket(cfg.RPD, 24*time.Hour, cfg.StartRPD, t),
		tpd: newBucket(cfg.TPD, 24*time.Hour, cfg.StartTPD, t),
	}
}

type message struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

type request struct {
	Model               string    `json:"model"`
	Messages            []message `json:"messages"`
	MaxCompletionTokens int       `json:"max_completion_tokens"`
	MaxTokens           int       `json:"max_tokens"`
	Stream              bool      `json:"stream"`
}

// plan is everything decided under the lock for one admitted call.
type plan struct {
	tokensIn   int
	firstToken time.Duration
	fail500    bool
	dropAfter  int // piece index to cut the connection at; -1 = never
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost || !strings.HasSuffix(r.URL.Path, "/chat/completions") {
		http.NotFound(w, r)
		return
	}
	var req request
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || !req.Stream {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "", "body must be JSON with stream: true")
		return
	}

	p, refusal := s.admit(&req)
	if refusal != nil {
		pause(r.Context(), ms(s.cfg.RefusalMS))
		s.setLimitHeaders(w)
		w.Header().Set("retry-after", strconv.Itoa(int(math.Ceil(refusal.wait.Seconds()))))
		writeError(w, http.StatusTooManyRequests, refusal.kind, "rate_limit_exceeded", refusal.msg)
		return
	}
	defer s.release()

	if p.fail500 {
		pause(r.Context(), p.firstToken)
		writeError(w, http.StatusInternalServerError, "internal_server_error", "", "stand-in injected failure")
		return
	}
	if !pause(r.Context(), p.firstToken) {
		return // client gave up
	}
	s.stream(w, r.Context(), req, p)
}

// refusal is a 429 decision.
type refusal struct {
	kind string // "requests" or "tokens", as in Groq's body
	wait time.Duration
	msg  string
}

// admit checks every limit before taking from any, so a refused call
// consumes nothing. It also fixes this call's random draws.
func (s *Server) admit(req *request) (plan, *refusal) {
	tokensIn := s.cfg.PromptOverheadTokens
	for _, m := range req.Messages {
		tokensIn += int(float64(len(m.Content)) / s.cfg.CharsPerToken)
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()

	if s.cfg.MaxInFlight > 0 && s.inFlight >= s.cfg.MaxInFlight {
		return plan{}, &refusal{"requests", time.Second, fmt.Sprintf("Too many requests in flight: Limit %d.", s.cfg.MaxInFlight)}
	}
	checks := []struct {
		b    *bucket
		n    float64
		kind string
		name string
	}{
		{s.rpm, 1, "requests", "requests per minute (RPM)"},
		{s.rpd, 1, "requests", "requests per day (RPD)"},
		{s.tpm, float64(tokensIn), "tokens", "tokens per minute (TPM)"},
		{s.tpd, float64(tokensIn), "tokens", "tokens per day (TPD)"},
	}
	for _, c := range checks {
		if wait := c.b.wait(c.n, now); wait > 0 {
			msg := fmt.Sprintf("Rate limit reached for model `%s` on %s: Limit %d, Requested %d. Please try again in %s.",
				req.Model, c.name, int(c.b.capacity), int(c.n), wait.Round(time.Millisecond))
			return plan{}, &refusal{c.kind, wait, msg}
		}
	}
	for _, c := range checks {
		c.b.charge(c.n, now)
	}

	s.inFlight++
	others := s.inFlight - 1
	base := s.cfg.FirstTokenMS[s.rng.IntN(len(s.cfg.FirstTokenMS))]
	p := plan{
		tokensIn:   tokensIn,
		firstToken: ms(base + s.cfg.InputMSPerToken*float64(tokensIn) + s.cfg.LoadMSPerInFlight*float64(others)),
		fail500:    s.rng.Float64() < s.cfg.ServerErrorRate,
		dropAfter:  -1,
	}
	if s.rng.Float64() < s.cfg.DropRate {
		p.dropAfter = s.rng.IntN(4) // cut within the first few pieces
	}
	return p, nil
}

func (s *Server) release() {
	s.mu.Lock()
	s.inFlight--
	s.mu.Unlock()
}

// stream writes the answer as SSE pieces of a few words each, then usage.
func (s *Server) stream(w http.ResponseWriter, ctx context.Context, req request, p plan) {
	maxOut := req.MaxCompletionTokens
	if maxOut == 0 {
		maxOut = req.MaxTokens
	}
	text, tokensOut := s.budget(answer(req.Messages), maxOut)

	s.setLimitHeaders(w)
	w.Header().Set("Content-Type", "text/event-stream")
	w.WriteHeader(http.StatusOK)
	flusher := w.(http.Flusher)

	for i, piece := range pieces(text, 3) {
		if i == p.dropAfter {
			panic(http.ErrAbortHandler) // net/http closes the connection
		}
		if i > 0 && !pause(ctx, ms(s.cfg.OutputMSPerToken*s.tokens(piece))) {
			return
		}
		writeChunk(w, map[string]any{"choices": []any{map[string]any{"delta": map[string]string{"content": piece}}}})
		flusher.Flush()
	}

	s.mu.Lock()
	s.tpm.charge(float64(tokensOut), s.now())
	s.tpd.charge(float64(tokensOut), s.now())
	s.mu.Unlock()

	writeChunk(w, map[string]any{"choices": []any{}, "usage": map[string]int{"prompt_tokens": p.tokensIn, "completion_tokens": tokensOut}})
	fmt.Fprint(w, "data: [DONE]\n\n")
	flusher.Flush()
}

// budget applies max output tokens. Hidden reasoning is spent first, so a
// small budget gives an empty answer, as the probe showed (DECISIONS D7).
func (s *Server) budget(text string, maxOut int) (string, int) {
	content := int(s.tokens(text))
	total := s.cfg.ReasoningTokens + content
	if maxOut <= 0 || total <= maxOut {
		return text, total
	}
	room := maxOut - s.cfg.ReasoningTokens
	if room <= 0 {
		return "", maxOut
	}
	cut := int(float64(room) * s.cfg.CharsPerToken)
	return text[:min(cut, len(text))], maxOut
}

func (s *Server) tokens(text string) float64 {
	return math.Ceil(float64(len(text)) / s.cfg.CharsPerToken)
}

// setLimitHeaders mirrors Groq: *-requests = per day, *-tokens = per minute.
func (s *Server) setLimitHeaders(w http.ResponseWriter) {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()
	h := w.Header()
	if s.rpd != nil {
		h.Set("x-ratelimit-limit-requests", strconv.Itoa(int(s.rpd.capacity)))
		h.Set("x-ratelimit-remaining-requests", strconv.Itoa(s.rpd.remaining(now)))
		h.Set("x-ratelimit-reset-requests", s.rpd.untilFull(now).Round(10*time.Millisecond).String())
	}
	if s.tpm != nil {
		h.Set("x-ratelimit-limit-tokens", strconv.Itoa(int(s.tpm.capacity)))
		h.Set("x-ratelimit-remaining-tokens", strconv.Itoa(s.tpm.remaining(now)))
		h.Set("x-ratelimit-reset-tokens", s.tpm.untilFull(now).Round(time.Millisecond).String())
	}
}

// pieces splits text into groups of n words, keeping the separating
// spaces so the concatenation equals the original.
func pieces(text string, n int) []string {
	words := strings.SplitAfter(text, " ")
	var out []string
	for i := 0; i < len(words); i += n {
		out = append(out, strings.Join(words[i:min(i+n, len(words))], ""))
	}
	return out
}

func writeChunk(w http.ResponseWriter, v any) {
	b, _ := json.Marshal(v)
	fmt.Fprintf(w, "data: %s\n\n", b)
}

func writeError(w http.ResponseWriter, status int, typ, code, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	body := map[string]any{"error": map[string]string{"message": msg, "type": typ, "code": code}}
	json.NewEncoder(w).Encode(body)
}

// pause sleeps for d unless ctx ends first; it reports whether it slept fully.
func pause(ctx context.Context, d time.Duration) bool {
	if d <= 0 {
		return ctx.Err() == nil
	}
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-t.C:
		return true
	case <-ctx.Done():
		return false
	}
}

func ms(v float64) time.Duration { return time.Duration(v * float64(time.Millisecond)) }

package standin

import (
	"context"
	"errors"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"relay/internal/llm"
)

// fakeClock is a settable clock shared by the server under test.
type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func (c *fakeClock) now() time.Time { c.mu.Lock(); defer c.mu.Unlock(); return c.t }
func (c *fakeClock) add(d time.Duration) {
	c.mu.Lock()
	c.t = c.t.Add(d)
	c.mu.Unlock()
}

// fastConfig keeps calibrated limits but removes all delays.
func fastConfig() Config {
	c := Default()
	c.FirstTokenMS = []float64{0}
	c.InputMSPerToken, c.OutputMSPerToken, c.LoadMSPerInFlight, c.RefusalMS = 0, 0, 0, 0
	return c
}

// start runs a stand-in and returns the real llm client pointed at it:
// the same code path the pipeline uses against Groq.
func start(t *testing.T, cfg Config) (*llm.HTTPClient, *fakeClock) {
	t.Helper()
	clock := &fakeClock{t: time.Unix(1_800_000_000, 0)}
	srv := httptest.NewServer(newWithClock(cfg, clock.now))
	t.Cleanup(srv.Close)
	return llm.NewHTTP(srv.URL, ""), clock
}

func ask(c *llm.HTTPClient, content string, maxTokens int) (*llm.Response, error) {
	return c.Complete(context.Background(), llm.Request{
		Model: "stand-in", MaxTokens: maxTokens,
		Messages: []llm.Message{{Role: "user", Content: content}},
	})
}

const prompt = "Question: what is it?\n[1706.03762v7#4] The Transformer uses multi-head attention in three different ways"

func TestAnswersByQuotingFirstChunk(t *testing.T) {
	c, _ := start(t, fastConfig())
	resp, err := ask(c, prompt, 500)
	if err != nil {
		t.Fatal(err)
	}
	want := `The papers state: "The Transformer uses multi-head attention in three different ways" [1706.03762v7#4].`
	if resp.Text != want {
		t.Errorf("text = %q", resp.Text)
	}
	if resp.TokensIn <= 72 || resp.TokensOut <= 20 {
		t.Errorf("tokens in=%d out=%d", resp.TokensIn, resp.TokensOut)
	}
	if resp.Limits.LimitTokens != 8000 || resp.Limits.LimitRequests != 1000 || resp.Limits.RemainingRequests != 999 {
		t.Errorf("limits headers: %+v", resp.Limits)
	}
}

func TestRefusesWithoutChunks(t *testing.T) {
	c, _ := start(t, fastConfig())
	resp, err := ask(c, "What is the capital of France?", 500)
	if err != nil || resp.Text != "The papers do not say." {
		t.Errorf("got %v, %v", resp, err)
	}
}

func TestSmallMaxTokensGivesEmptyAnswer(t *testing.T) {
	c, _ := start(t, fastConfig()) // ReasoningTokens = 20
	resp, err := ask(c, prompt, 16)
	if err != nil || resp.Text != "" || resp.TokensOut != 16 {
		t.Errorf("got text=%q out=%d err=%v", resp.Text, resp.TokensOut, err)
	}
}

func TestRPMLimitAndRefill(t *testing.T) {
	cfg := fastConfig()
	cfg.RPM = 2
	c, clock := start(t, cfg)
	for i := 0; i < 2; i++ {
		if _, err := ask(c, "hi", 100); err != nil {
			t.Fatalf("call %d: %v", i, err)
		}
	}
	_, err := ask(c, "hi", 100)
	var rl *llm.RateLimitError
	if !errors.As(err, &rl) || rl.RetryAfter != 30*time.Second || !strings.Contains(rl.Body, `"type":"requests"`) {
		t.Fatalf("want RPM 429 with retry-after 30s, got %T %v", err, err)
	}
	clock.add(30 * time.Second) // one request refills every 30s at 2 RPM
	if _, err := ask(c, "hi", 100); err != nil {
		t.Errorf("after refill: %v", err)
	}
}

func TestTPMLimitIsTokens(t *testing.T) {
	cfg := fastConfig()
	cfg.TPM = 200
	c, _ := start(t, cfg)
	_, err := ask(c, strings.Repeat("word ", 300), 100) // ~372 tokens > 200
	var rl *llm.RateLimitError
	if !errors.As(err, &rl) || !strings.Contains(rl.Body, `"type":"tokens"`) {
		t.Errorf("want TPM 429, got %T %v", err, err)
	}
}

func TestDailyBudgetExhausted(t *testing.T) {
	cfg := fastConfig()
	cfg.StartRPD = 0
	c, clock := start(t, cfg)
	_, err := ask(c, "hi", 100)
	var rl *llm.RateLimitError
	if !errors.As(err, &rl) || rl.RetryAfter != 87*time.Second { // 86.4s, rounded up like Groq
		t.Fatalf("want RPD 429 retry-after 87s, got %T %v", err, err)
	}
	clock.add(87 * time.Second)
	if _, err := ask(c, "hi", 100); err != nil {
		t.Errorf("one request should trickle back: %v", err)
	}
}

func TestRefusedCallConsumesNothing(t *testing.T) {
	cfg := fastConfig()
	cfg.RPM, cfg.TPM = 5, 200
	c, _ := start(t, cfg)
	ask(c, strings.Repeat("word ", 300), 100) // refused on TPM
	resp, err := ask(c, "hi", 100)
	if err != nil || resp.Limits.RemainingRequests != 999 {
		t.Errorf("refused call should not count: rem=%d err=%v", resp.Limits.RemainingRequests, err)
	}
}

func TestInjectedFailures(t *testing.T) {
	cfg := fastConfig()
	cfg.ServerErrorRate = 1
	c, _ := start(t, cfg)
	var se *llm.ServerError
	if _, err := ask(c, prompt, 500); !errors.As(err, &se) {
		t.Errorf("want ServerError, got %T %v", err, err)
	}

	cfg = fastConfig()
	cfg.DropRate = 1
	c, _ = start(t, cfg)
	var ce *llm.ConnError
	if _, err := ask(c, prompt, 500); !errors.As(err, &ce) {
		t.Errorf("want ConnError, got %T %v", err, err)
	}
}

func TestInFlightCap(t *testing.T) {
	cfg := fastConfig()
	cfg.MaxInFlight = 1
	cfg.FirstTokenMS = []float64{150} // hold the first call open
	c, _ := start(t, cfg)

	done := make(chan error)
	go func() { _, err := ask(c, "hi", 100); done <- err }()
	time.Sleep(50 * time.Millisecond)
	_, err := ask(c, "hi", 100)
	var rl *llm.RateLimitError
	if !errors.As(err, &rl) {
		t.Errorf("second concurrent call: want 429, got %T %v", err, err)
	}
	if err := <-done; err != nil {
		t.Errorf("first call: %v", err)
	}
}

func TestSlowerUnderLoad(t *testing.T) {
	s := newWithClock(Config{FirstTokenMS: []float64{100}, LoadMSPerInFlight: 10, CharsPerToken: 5}, time.Now)
	var delays []time.Duration
	for i := 0; i < 3; i++ { // three calls admitted, none released
		p, ref := s.admit(&request{})
		if ref != nil {
			t.Fatal(ref.msg)
		}
		delays = append(delays, p.firstToken)
	}
	want := []time.Duration{100 * time.Millisecond, 110 * time.Millisecond, 120 * time.Millisecond}
	for i := range want {
		if delays[i] != want[i] {
			t.Errorf("call %d first-token delay %v, want %v", i, delays[i], want[i])
		}
	}
}

func TestBucket(t *testing.T) {
	t0 := time.Unix(0, 0)
	b := newBucket(60, time.Minute, -1, t0) // 1 per second
	b.charge(60, t0)
	if w := b.wait(1, t0); w != time.Second {
		t.Errorf("wait = %v, want 1s", w)
	}
	if w := b.wait(1, t0.Add(time.Second)); w != 0 {
		t.Errorf("after 1s wait = %v, want 0", w)
	}
	if got := b.untilFull(t0.Add(time.Second)); got != 59*time.Second {
		t.Errorf("untilFull = %v", got)
	}
	var none *bucket
	if none.wait(1e9, t0) != 0 {
		t.Error("nil bucket must never limit")
	}
}

