// Package results writes results.csv: one row per request, the single
// source every table is computed from (DESIGN.md §6).
package results

import (
	"encoding/csv"
	"fmt"
	"io"
	"os"
	"strconv"
	"sync"
	"time"
)

// Columns: the brief's required columns in its order, then our extras.
var Columns = []string{
	"request_id", "scenario", "source", "start_time", "first_token_ms", "total_ms",
	"status", "retries", "tokens_in", "tokens_out", "retrieval_setting", "answer_grade",
	// extras
	"question_id", "queue_wait_ms", "model_ms", "queue_len_at_arrival",
	"ladder_level", "n_429_seen", "error_detail",
}

// Allowed values, from the brief.
var (
	Statuses = map[string]bool{"ok": true, "rate_limited": true, "timeout": true, "error": true}
	Grades   = map[string]bool{"": true, "correct": true, "wrong": true, "refused_correctly": true, "refused_wrongly": true}
	Sources  = map[string]bool{"real": true, "stand-in": true}
)

// Row is one request. Durations are measured from the request's
// *scheduled* start, so a late generator cannot hide queueing.
// FirstTokenMS < 0 means no token ever reached the person (written empty).
type Row struct {
	RequestID        string
	Scenario         string
	Source           string // "real" or "stand-in"
	Start            time.Time
	FirstTokenMS     int64
	TotalMS          int64
	Status           string
	Retries          int
	TokensIn         int
	TokensOut        int
	RetrievalSetting string
	AnswerGrade      string // only for eval rows

	QuestionID        string
	QueueWaitMS       int64
	ModelMS           int64
	QueueLenAtArrival int
	LadderLevel       int // 0..3
	N429Seen          int
	ErrorDetail       string
}

// Validate rejects rows the tables could not use.
func (r Row) Validate() error {
	switch {
	case r.RequestID == "":
		return fmt.Errorf("empty request_id")
	case !Statuses[r.Status]:
		return fmt.Errorf("%s: bad status %q", r.RequestID, r.Status)
	case !Grades[r.AnswerGrade]:
		return fmt.Errorf("%s: bad answer_grade %q", r.RequestID, r.AnswerGrade)
	case !Sources[r.Source]:
		return fmt.Errorf("%s: bad source %q", r.RequestID, r.Source)
	case r.LadderLevel < 0 || r.LadderLevel > 3:
		return fmt.Errorf("%s: bad ladder_level %d", r.RequestID, r.LadderLevel)
	}
	return nil
}

func (r Row) record() []string {
	i := strconv.Itoa
	i64 := func(v int64) string { return strconv.FormatInt(v, 10) }
	firstToken := ""
	if r.FirstTokenMS >= 0 {
		firstToken = i64(r.FirstTokenMS)
	}
	return []string{
		r.RequestID, r.Scenario, r.Source, r.Start.UTC().Format(time.RFC3339Nano), firstToken, i64(r.TotalMS),
		r.Status, i(r.Retries), i(r.TokensIn), i(r.TokensOut), r.RetrievalSetting, r.AnswerGrade,
		r.QuestionID, i64(r.QueueWaitMS), i64(r.ModelMS), i(r.QueueLenAtArrival),
		i(r.LadderLevel), i(r.N429Seen), r.ErrorDetail,
	}
}

// Writer appends rows to one CSV file, safe for concurrent use. Each row
// is flushed at once so a crashed run keeps what it measured.
type Writer struct {
	mu sync.Mutex
	f  *os.File
	w  *csv.Writer
}

// Open appends to path, writing the header only if the file is new or
// empty, so every run lands in the same results.csv.
func Open(path string) (*Writer, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return nil, err
	}
	info, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, err
	}
	w := &Writer{f: f, w: csv.NewWriter(f)}
	if info.Size() == 0 {
		if err := w.writeLine(Columns); err != nil {
			f.Close()
			return nil, err
		}
	}
	return w, nil
}

// Write validates and appends one row.
func (w *Writer) Write(r Row) error {
	if err := r.Validate(); err != nil {
		return err
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.writeLine(r.record())
}

func (w *Writer) writeLine(rec []string) error {
	if err := w.w.Write(rec); err != nil {
		return err
	}
	w.w.Flush()
	return w.w.Error()
}

func (w *Writer) Close() error { return w.f.Close() }

// ReadAll parses a results file back into string records keyed by column,
// for tests and sanity checks.
func ReadAll(r io.Reader) ([]map[string]string, error) {
	recs, err := csv.NewReader(r).ReadAll()
	if err != nil || len(recs) == 0 {
		return nil, err
	}
	head := recs[0]
	out := make([]map[string]string, 0, len(recs)-1)
	for _, rec := range recs[1:] {
		m := make(map[string]string, len(head))
		for i, col := range head {
			m[col] = rec[i]
		}
		out = append(out, m)
	}
	return out, nil
}

package results

import (
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"sync"
	"testing"
	"time"
)

func row(id string) Row {
	return Row{
		RequestID: id, Scenario: "steady", Source: "stand-in",
		Start:        time.Date(2026, 11, 12, 10, 0, 0, 5e6, time.UTC),
		FirstTokenMS: 412, TotalMS: 980, Status: "ok", TokensIn: 1500, TokensOut: 120,
		RetrievalSetting: "R2", ErrorDetail: `quote "x", missing`,
	}
}

func TestRequiredColumnsComeFirstInBriefOrder(t *testing.T) {
	brief := strings.Split("request_id,scenario,source,start_time,first_token_ms,total_ms,status,retries,tokens_in,tokens_out,retrieval_setting,answer_grade", ",")
	if !reflect.DeepEqual(Columns[:len(brief)], brief) {
		t.Errorf("columns = %v", Columns)
	}
	if len(row("x").record()) != len(Columns) {
		t.Error("record and header lengths differ")
	}
}

func TestAppendWritesHeaderOnce(t *testing.T) {
	path := filepath.Join(t.TempDir(), "results.csv")
	for run := 0; run < 2; run++ {
		w, err := Open(path)
		if err != nil {
			t.Fatal(err)
		}
		if err := w.Write(row(fmt.Sprintf("r%d", run))); err != nil {
			t.Fatal(err)
		}
		w.Close()
	}
	f, _ := os.Open(path)
	defer f.Close()
	rows, err := ReadAll(f)
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 2 || rows[0]["request_id"] != "r0" || rows[1]["request_id"] != "r1" {
		t.Fatalf("rows = %v", rows)
	}
	r := rows[0]
	if r["start_time"] != "2026-11-12T10:00:00.005Z" || r["first_token_ms"] != "412" || r["error_detail"] != `quote "x", missing` {
		t.Errorf("round trip: %v", r)
	}
}

func TestNoFirstTokenIsEmpty(t *testing.T) {
	r := row("x")
	r.FirstTokenMS, r.Status = -1, "timeout"
	if got := r.record()[4]; got != "" {
		t.Errorf("first_token_ms = %q, want empty", got)
	}
}

func TestValidate(t *testing.T) {
	bad := []func(*Row){
		func(r *Row) { r.RequestID = "" },
		func(r *Row) { r.Status = "rate-limited" },
		func(r *Row) { r.AnswerGrade = "partly" },
		func(r *Row) { r.Source = "fake" },
		func(r *Row) { r.LadderLevel = 4 },
	}
	for i, mutate := range bad {
		r := row("x")
		mutate(&r)
		if r.Validate() == nil {
			t.Errorf("case %d should be rejected", i)
		}
	}
	if err := row("x").Validate(); err != nil {
		t.Error(err)
	}
}

func TestConcurrentWritesKeepRowsWhole(t *testing.T) {
	path := filepath.Join(t.TempDir(), "results.csv")
	w, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			w.Write(row(fmt.Sprintf("r%d", i)))
		}()
	}
	wg.Wait()
	w.Close()
	f, _ := os.Open(path)
	defer f.Close()
	rows, err := ReadAll(f)
	if err != nil || len(rows) != 50 {
		t.Fatalf("got %d rows, err %v", len(rows), err)
	}
}

// Package retrieve finds the chunks most relevant to a query with BM25.
package retrieve

import (
	"strings"
	"unicode"
)

// stopwords are dropped from queries and chunks alike. Kept small on
// purpose: words like "not", "without" or "only" change meaning and stay.
var stopwords = map[string]bool{
	"a": true, "an": true, "and": true, "are": true, "as": true, "at": true, "be": true,
	"by": true, "do": true, "does": true, "for": true, "from": true, "how": true, "in": true,
	"is": true, "it": true, "its": true, "of": true, "on": true, "or": true, "that": true,
	"the": true, "their": true, "this": true, "to": true, "was": true, "were": true,
	"what": true, "when": true, "which": true, "who": true, "why": true, "with": true,
}

// Tokenize lowercases text and splits it on anything that is not a letter
// or digit, dropping stopwords. "Multi-Head" -> ["multi", "head"],
// "d_k" -> ["d", "k"], "28.4" -> ["28", "4"]. No stemming: "chunk" and
// "chunking" are different terms (a known limit, see DESIGN §3).
func Tokenize(text string) []string {
	fields := strings.FieldsFunc(strings.ToLower(text), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r)
	})
	out := fields[:0]
	for _, f := range fields {
		if !stopwords[f] {
			out = append(out, f)
		}
	}
	return out
}

package retrieve

import (
	"reflect"
	"testing"
)

func TestTokenize(t *testing.T) {
	tests := map[string][]string{
		"":                                   {},
		"The Transformer":                    {"transformer"},
		"Multi-Head Attention":               {"multi", "head", "attention"},
		"scaled by 1/sqrt(d_k)":              {"scaled", "1", "sqrt", "d", "k"},
		"BLEU of 28.4 on WMT 2014":           {"bleu", "28", "4", "wmt", "2014"},
		"does NOT use recurrence":            {"not", "use", "recurrence"},
		"Mimi’s RVQ, Moshi's “Inner Monologue”": {"mimi", "s", "rvq", "moshi", "s", "inner", "monologue"},
		"Cernocký":                           {"cernocký"},
	}
	for in, want := range tests {
		got := Tokenize(in)
		if len(got) == 0 && len(want) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("Tokenize(%q) = %q, want %q", in, got, want)
		}
	}
}

