	}
	hits = ix.Search("speech model", 10)
	if !near(hits[0].Score, 1.241313) || !near(hits[0].Norm, 0.506329) || !near(hits[1].Score, 0.127035) {
		t.Errorf("speech model: %+v", hits)
	}
