	// c0 and c1 tie and must keep corpus order for reproducible runs.
	got := ids(NewIndex(toy).Search("model", 10))
	want := []string{"c2", "c0", "c1"}
	if len(got) != 3 || got[0] != want[0] || got[1] != want[1] || got[2] != want[2] {
