package retrieve

import (
	"math"
	"sort"

	"relay/internal/corpus"
)

// BM25 parameters, the usual defaults.
//   - k1: how fast repeated words stop adding score (saturation).
//   - b:  how much a long chunk is penalised (0 = never, 1 = fully).
const (
	k1 = 1.2
	b  = 0.75
)

// Hit is one search result.
//   - Score is raw BM25: good for ranking within one query.
//   - Norm is Score divided by the best score this query could ever get, so
//     it lies in [0,1) and can be compared across queries of different
//     lengths. The refusal threshold T is applied to Norm.
type Hit struct {
	Chunk corpus.Chunk
	Score float64
	Norm  float64
}

// Index holds the per-chunk counts BM25 needs, computed once.
// It is read-only after NewIndex, so Search is safe from many goroutines.
type Index struct {
	chunks []corpus.Chunk
	tf     []map[string]int // tf[i][term] = times term appears in chunk i
	length []int            // length[i] = tokens in chunk i
	df     map[string]int   // df[term] = number of chunks containing term
	avgLen float64
}

// NewIndex tokenizes every chunk once and records the counts.
func NewIndex(chunks []corpus.Chunk) *Index {
	ix := &Index{
		chunks: chunks,
		tf:     make([]map[string]int, len(chunks)),
		length: make([]int, len(chunks)),
		df:     map[string]int{},
	}
	total := 0
	for i, c := range chunks {
		terms := Tokenize(c.Text)
		counts := make(map[string]int, len(terms))
		for _, t := range terms {
			counts[t]++
		}
		for t := range counts {
			ix.df[t]++
		}
		ix.tf[i], ix.length[i] = counts, len(terms)
		total += len(terms)
	}
	if len(chunks) > 0 {
		ix.avgLen = float64(total) / float64(len(chunks))
	}
	return ix
}

// idf is how rare a term is. Rare terms count more. This form is never
// negative, even for a term in every chunk.
func (ix *Index) idf(term string) float64 {
	n, N := float64(ix.df[term]), float64(len(ix.chunks))
	return math.Log(1 + (N-n+0.5)/(n+0.5))
}

// Search returns up to k chunks with score > 0, best first. Equal scores
// keep corpus order so runs are reproducible.
func (ix *Index) Search(query string, k int) []Hit {
	if k <= 0 {
		return nil
	}
	terms := unique(Tokenize(query))
	if len(terms) == 0 || len(ix.chunks) == 0 {
		return nil
	}

	// The best possible score: every term matched, saturated, in a very
	// short chunk. Words the corpus never uses still count here, so an
	// off-topic query cannot reach a high Norm.
	best := 0.0
	idf := make([]float64, len(terms))
	for j, t := range terms {
		idf[j] = ix.idf(t)
		best += idf[j] * (k1 + 1)
	}

	var hits []Hit
	for i := range ix.chunks {
		s := ix.score(i, terms, idf)
		if s > 0 {
			hits = append(hits, Hit{Chunk: ix.chunks[i], Score: s, Norm: s / best})
		}
	}
	sort.SliceStable(hits, func(a, c int) bool { return hits[a].Score > hits[c].Score })
	if len(hits) > k {
		hits = hits[:k]
	}
	return hits
}

// score is the BM25 sum over query terms for chunk i:
//
//	idf(t) * tf*(k1+1) / (tf + k1*(1 - b + b*len/avgLen))
func (ix *Index) score(i int, terms []string, idf []float64) float64 {
	lengthNorm := k1 * (1 - b + b*float64(ix.length[i])/ix.avgLen)
	s := 0.0
	for j, t := range terms {
		tf := float64(ix.tf[i][t])
		if tf == 0 {
			continue
		}
		s += idf[j] * tf * (k1 + 1) / (tf + lengthNorm)
	}
	return s
}

// unique drops repeated query words: "attention attention" asks the same
// thing as "attention".
func unique(terms []string) []string {
	seen := make(map[string]bool, len(terms))
	out := terms[:0:0]
	for _, t := range terms {
		if !seen[t] {
			seen[t] = true
			out = append(out, t)
		}
	}
	return out
}

// Package pipeline answers a question: rewrite, retrieve, decide, draft,
// verify (DESIGN.md §2).
package pipeline

import (
	"fmt"
	"regexp"
	"strings"

	"relay/internal/corpus"
)

// RefusalText is the exact sentence the model is told to use when the
// chunks do not answer the question.
const RefusalText = "The papers do not say."

// minEvidenceWords: a quote shorter than this proves too little ("the
// model") to count as the evidence every answer must carry.
const minEvidenceWords = 3

// Verdict is the outcome of checking one draft.
type Verdict struct {
	OK       bool
	Refusal  bool     // the draft is a refusal (OK is then true)
	Cited    []string // chunk ids cited, first-seen order, no repeats
	Problems []string // why it failed, in words the redraft prompt can use
}

var (
	citeRe  = regexp.MustCompile(`\[([^\[\]\s]+#\d+)\]`) // [1706.03762v7#12]
	quoteRe = regexp.MustCompile(`"([^"]+)"|“([^”]+)”`)  // "..." or “...”
)

// Verify checks a draft with plain string rules, no model:
//  1. it is not empty;
//  2. a refusal is accepted as is;
//  3. it cites at least one chunk, and only chunks that were retrieved;
//  4. every quote appears word for word in the chunk cited right after it;
//  5. at least one quote is 3+ words long, so the answer carries evidence.
//
// Known limit: a correct quote placed next to a wrong claim passes.
func Verify(answer string, retrieved []corpus.Chunk) Verdict {
	var v Verdict
	text := strings.TrimSpace(answer)
	if text == "" {
		return fail(v, "the answer is empty")
	}
	if isRefusal(text) {
		return Verdict{OK: true, Refusal: true}
	}

	byID := make(map[string]corpus.Chunk, len(retrieved))
	for _, c := range retrieved {
		byID[c.ID] = c
	}

	cites := citeRe.FindAllStringSubmatchIndex(text, -1)
	if len(cites) == 0 {
		v.Problems = append(v.Problems, "no chunk is cited; cite each claim as [chunk id]")
	}
	seen := map[string]bool{}
	for _, m := range cites {
		id := text[m[2]:m[3]]
		if seen[id] {
			continue
		}
		seen[id] = true
		v.Cited = append(v.Cited, id)
		if _, ok := byID[id]; !ok {
			v.Problems = append(v.Problems, fmt.Sprintf("[%s] is cited but was not one of the provided chunks", id))
		}
	}

	evidence := false
	for _, q := range quoteRe.FindAllStringSubmatchIndex(text, -1) {
		quote := group(text, q)
		id, ok := citationAfter(text, cites, q[1])
		if !ok {
			v.Problems = append(v.Problems, fmt.Sprintf("the quote %q has no citation after it", quote))
			continue
		}
		chunk, known := byID[id]
		if !known {
			continue // already reported above
		}
		if !strings.Contains(normalize(chunk.Text), normalize(trimEnd(quote))) {
			v.Problems = append(v.Problems, fmt.Sprintf("the quote %q is not word for word in [%s]", quote, id))
			continue
		}
		if len(strings.Fields(quote)) >= minEvidenceWords {
			evidence = true
		}
	}
	if !evidence && len(cites) > 0 {
		v.Problems = append(v.Problems, fmt.Sprintf("no exact quote of at least %d words supports the answer", minEvidenceWords))
	}

	v.OK = len(v.Problems) == 0
	return v
}

func fail(v Verdict, problem string) Verdict {
	v.Problems = append(v.Problems, problem)
	return v
}

// isRefusal accepts the refusal sentence at the start, ignoring case and
// spacing, so "The papers do not say. They discuss X instead." still counts.
func isRefusal(text string) bool {
	return strings.HasPrefix(strings.ToLower(normalize(text)), strings.ToLower(normalize(RefusalText)))
}

// group returns whichever quote alternative matched (straight or curly).
func group(text string, m []int) string {
	if m[2] >= 0 {
		return text[m[2]:m[3]]
	}
	return text[m[4]:m[5]]
}

// citationAfter returns the id of the first citation starting at or after
// pos: the citation a quote belongs to.
func citationAfter(text string, cites [][]int, pos int) (string, bool) {
	for _, c := range cites {
		if c[0] >= pos {
			return text[c[2]:c[3]], true
		}
	}
	return "", false
}

// typography maps characters the PDFs and the model write differently.
var typography = strings.NewReplacer(
	"’", "'", "‘", "'", "“", `"`, "”", `"`,
	"–", "-", "—", "-", "‐", "-", " ", " ",
)

// normalize collapses whitespace and unifies typography. Case is kept:
// a quote must be word for word.
func normalize(s string) string {
	return strings.Join(strings.Fields(typography.Replace(s)), " ")
}

// trimEnd drops punctuation a writer puts inside the closing quote mark
// ("…as follows.") that may not follow the words in the source.
func trimEnd(s string) string {
	return strings.TrimRight(strings.TrimSpace(s), ".,;:!?")
}

package pipeline

import (
	"strings"
	"testing"

	"relay/internal/corpus"
)

var chunks = []corpus.Chunk{
	{ID: "1706.03762v7#9", Text: "We suspect that for large values of dk , the dot products grow large in magnitude, pushing the softmax function into regions where it has extremely small gradients"},
	{ID: "2410.00037v1#40", Text: "Mimi’s encoder projects a 24kHz waveform to a latent representation of 12.5 frames per second"},
}

func TestVerify(t *testing.T) {
	tests := []struct {
		name    string
		answer  string
		ok      bool
		refusal bool
		problem string // substring expected in Problems when !ok
	}{
		{"good answer",
			`Large dot products push "the softmax function into regions where it has extremely small gradients" [1706.03762v7#9].`,
			true, false, ""},
		{"curly quotes, straight apostrophe, extra spaces, period inside quote",
			`The codec runs at 12.5 Hz: “Mimi's encoder projects a 24kHz   waveform.” [2410.00037v1#40]`,
			true, false, ""},
		{"refusal", "The papers do not say.", true, true, ""},
		{"refusal with explanation, different case", "the papers do NOT say. They only cover EN-DE and EN-FR.", true, true, ""},
		{"empty", "  ", false, false, "empty"},
		{"no citation", `They say "the dot products grow large in magnitude".`, false, false, "no chunk is cited"},
		{"invented chunk id", `"the dot products grow large in magnitude" [1706.03762v7#99].`, false, false, "not one of the provided chunks"},
		{"quote not in chunk", `"the dot products shrink toward zero" [1706.03762v7#9].`, false, false, "not word for word"},
		{"right quote, wrong chunk", `"the dot products grow large in magnitude" [2410.00037v1#40].`, false, false, "not word for word"},
		{"quote with no citation after it", `[1706.03762v7#9] says "the dot products grow large in magnitude".`, false, false, "no citation after it"},
		{"citation but no quote", `Scaling keeps gradients healthy [1706.03762v7#9].`, false, false, "no exact quote"},
