// Package traffic decides when model calls may run: the limiter keeps us
// inside the provider's limits, the retry policy handles failures, and
// admission queues requests or steps them down the degradation ladder.
package traffic

import (
	"sync"
	"time"

	"relay/internal/bucket"
	"relay/internal/llm"
)

// Limits are the provider's, as measured by the probe (Table 1).
type Limits struct {
	RPM, TPM int // per minute
	RPD, TPD int // per day
}

// GroqFree is what the probe found for openai/gpt-oss-20b on the free
// tier. TPD is from the docs only (not measured).
var GroqFree = Limits{RPM: 30, TPM: 8000, RPD: 1000, TPD: 200000}

// Which limit is in the way. Admission treats them differently: a minute
// limit means "wait or give less", a day limit means "budget is gone".
const (
	ByMinute = "minute"
	ByDay    = "day"
	ByPause  = "retry-after" // the provider told us to back off
)

// Limiter is our own model of the provider's buckets. We trust it over
// the provider: the probe showed Groq letting 34 of 35 burst calls past a
// 30 RPM limit (DECISIONS D6). Safe for concurrent use.
type Limiter struct {
	mu          sync.Mutex
	now         func() time.Time
	rpm, tpm    *bucket.Bucket
	rpd, tpd    *bucket.Bucket
	pausedUntil time.Time
}

// NewLimiter starts with full buckets. now is the clock (nil = real time).
func NewLimiter(l Limits, now func() time.Time) *Limiter {
	if now == nil {
		now = time.Now
	}
	t := now()
	return &Limiter{
		now: now,
		rpm: bucket.New(l.RPM, time.Minute, -1, t),
		tpm: bucket.New(l.TPM, time.Minute, -1, t),
		rpd: bucket.New(l.RPD, 24*time.Hour, -1, t),
		tpd: bucket.New(l.TPD, 24*time.Hour, -1, t),
	}
}

// Wait says how long until `requests` calls totalling `tokens` could all
// start, and which limit is the reason. It reserves nothing; admission
// uses it to estimate a queue's wait. bucket.Never = can never fit.
func (l *Limiter) Wait(requests, tokens int) (time.Duration, string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.wait(float64(requests), float64(tokens))
}

func (l *Limiter) wait(requests, tokens float64) (time.Duration, string) {
	now := l.now()
	var longest time.Duration
	why := ""
	consider := func(d time.Duration, reason string) {
		if d > longest {
			longest, why = d, reason
		}
	}
	consider(l.pausedUntil.Sub(now), ByPause)
	consider(l.rpm.Wait(requests, now), ByMinute)
	consider(l.tpm.Wait(tokens, now), ByMinute)
	consider(l.rpd.Wait(requests, now), ByDay)
	consider(l.tpd.Wait(tokens, now), ByDay)
	return longest, why
}

// TryReserve takes room for one call of about `tokens` tokens if every
// limit allows it right now. Otherwise it reserves nothing and returns
// the wait and its reason. tokens should be input + max output: we
// over-reserve and give back the rest in Finish.
func (l *Limiter) TryReserve(tokens int) (*Reservation, time.Duration, string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if wait, why := l.wait(1, float64(tokens)); wait > 0 {
		return nil, wait, why
	}
	now := l.now()
	l.rpm.Charge(1, now)
	l.rpd.Charge(1, now)
	l.tpm.Charge(float64(tokens), now)
	l.tpd.Charge(float64(tokens), now)
	return &Reservation{l: l, tokens: tokens}, 0, ""
}

// Reservation is room taken for one call. Exactly one of Finish or
// Cancel should be called; extra calls do nothing.
type Reservation struct {
	l      *Limiter
	tokens int
	done   bool
}

// Finish settles the reservation with the tokens the provider reported:
// unused tokens go back, an overrun is charged. The request still counts.
func (r *Reservation) Finish(actualTokens int) {
	r.settle(float64(r.tokens-actualTokens), 0)
}

// Cancel returns everything: the call was never sent.
func (r *Reservation) Cancel() {
	r.settle(float64(r.tokens), 1)
}

func (r *Reservation) settle(tokensBack, requestsBack float64) {
	l := r.l
	l.mu.Lock()
	defer l.mu.Unlock()
	if r.done {
		return
	}
	r.done = true
	now := l.now()
	l.tpm.Charge(-tokensBack, now)
	l.tpd.Charge(-tokensBack, now)
	l.rpm.Charge(-requestsBack, now)
	l.rpd.Charge(-requestsBack, now)
}

// Observe corrects our count from the provider's headers (good-to-have
// #1). Groq's *-requests headers are per day, *-tokens per minute. We
// only ever lower our count: inside a burst the headers disagree with
// each other, so the lowest is the safe one to believe (DECISIONS D6).
func (l *Limiter) Observe(h llm.RateLimits) {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	if h.RemainingRequests >= 0 {
		l.rpd.LowerTo(float64(h.RemainingRequests), now)
	}
	if h.RemainingTokens >= 0 {
		l.tpm.LowerTo(float64(h.RemainingTokens), now)
	}
}

// PauseFor stops all new calls for d, after the provider answered 429
// with a retry hint. Extending is allowed, shortening is not.
func (l *Limiter) PauseFor(d time.Duration) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if until := l.now().Add(d); until.After(l.pausedUntil) {
		l.pausedUntil = until
	}
}

package traffic

import (
	"sync"
	"testing"
	"time"

	"relay/internal/bucket"
	"relay/internal/llm"
)

// clock is a settable fake clock for deterministic limiter tests.
type clock struct {
	mu sync.Mutex
	t  time.Time
}

func newClock() *clock { return &clock{t: time.Unix(1_800_000_000, 0)} }
func (c *clock) now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}
func (c *clock) add(d time.Duration) {
	c.mu.Lock()
	c.t = c.t.Add(d)
	c.mu.Unlock()
}

func reserve(t *testing.T, l *Limiter, tokens int) *Reservation {
	t.Helper()
	r, wait, why := l.TryReserve(tokens)
	if r == nil {
		t.Fatalf("reserve %d: blocked %v by %s", tokens, wait, why)
	}
	return r
}

func TestRequestsPerMinute(t *testing.T) {
	c := newClock()
	l := NewLimiter(GroqFree, c.now)
	for i := 0; i < 30; i++ {
		reserve(t, l, 10)
	}
	r, wait, why := l.TryReserve(10)
	if r != nil || wait != 2*time.Second || why != ByMinute { // 30/min refills one per 2s
		t.Fatalf("31st call: r=%v wait=%v why=%s", r, wait, why)
	}
	c.add(2 * time.Second)
	reserve(t, l, 10)
}

func TestTokensPerMinute(t *testing.T) {
	c := newClock()
	l := NewLimiter(GroqFree, c.now)
	reserve(t, l, 5000)
	_, wait, why := l.TryReserve(4000) // 1000 short at 8000/60 per second
	if want := 7500 * time.Millisecond; wait != want || why != ByMinute {
		t.Errorf("wait=%v why=%s, want %v minute", wait, why, want)
	}
}

func TestFinishGivesBackUnusedTokens(t *testing.T) {
	c := newClock()
	l := NewLimiter(GroqFree, c.now)
	reserve(t, l, 5000).Finish(1200)
	if wait, _ := l.Wait(1, 6800); wait != 0 {
		t.Errorf("after settling 1200 of 5000, 6800 should fit; wait=%v", wait)
	}
	if wait, _ := l.Wait(1, 6801); wait == 0 {
		t.Error("6801 should not fit")
	}
}

func TestFinishChargesOverrun(t *testing.T) {
	c := newClock()
	l := NewLimiter(GroqFree, c.now)
	reserve(t, l, 1000).Finish(3000)
	if wait, _ := l.Wait(1, 5001); wait == 0 {
		t.Error("an overrun of 2000 should be charged")
	}
}

func TestCancelReturnsEverythingOnce(t *testing.T) {
	c := newClock()
	l := NewLimiter(Limits{RPM: 1, TPM: 100}, c.now)
	r := reserve(t, l, 100)
	r.Cancel()
	r.Cancel()     // second call must not over-refund
	r.Finish(0)    // nor may a Finish after Cancel
	reserve(t, l, 100) // the request and tokens are back
	if r2, _, _ := l.TryReserve(1); r2 != nil {
		t.Error("double refund: a second request got through a 1 RPM limit")
	}
}

func TestDailyLimitIsReportedAsDay(t *testing.T) {
	c := newClock()
	l := NewLimiter(Limits{RPM: 100, RPD: 2}, c.now)
	reserve(t, l, 1)
	reserve(t, l, 1)
	_, wait, why := l.TryReserve(1)
	if why != ByDay || wait != 12*time.Hour { // 2 per day refill one per 12h
		t.Errorf("wait=%v why=%s", wait, why)
	}
}

func TestObserveOnlyLowers(t *testing.T) {
	c := newClock()
	l := NewLimiter(GroqFree, c.now)
	l.Observe(llm.RateLimits{RemainingTokens: 500, RemainingRequests: -1})
	if wait, _ := l.Wait(1, 501); wait == 0 {
		t.Error("header said 500 tokens left; 501 must wait")
	}
	l.Observe(llm.RateLimits{RemainingTokens: 7000, RemainingRequests: -1})
	if wait, _ := l.Wait(1, 501); wait == 0 {
		t.Error("a higher header value must not raise our count")
	}
	l.Observe(llm.RateLimits{RemainingTokens: -1, RemainingRequests: 0})
	if _, why := l.Wait(1, 1); why != ByDay {
		t.Errorf("remaining-requests 0 (per day) should block by day, got %q", why)
	}
}

func TestPauseFromRetryAfter(t *testing.T) {
	c := newClock()
	l := NewLimiter(GroqFree, c.now)
	l.PauseFor(3 * time.Second)
	l.PauseFor(1 * time.Second) // must not shorten
	if _, wait, why := l.TryReserve(1); wait != 3*time.Second || why != ByPause {
		t.Errorf("wait=%v why=%s", wait, why)
	}
	c.add(3 * time.Second)
	reserve(t, l, 1)
}

func TestLargerThanBucketNeverFits(t *testing.T) {
	l := NewLimiter(GroqFree, newClock().now)
	if _, wait, _ := l.TryReserve(9000); wait != bucket.Never {
		t.Errorf("9000 tokens > 8000 TPM should never fit, wait=%v", wait)
	}
}

func TestConcurrentReserveAndFinish(t *testing.T) {
	l := NewLimiter(Limits{RPM: 1000, TPM: 1_000_000}, nil)
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if r, _, _ := l.TryReserve(100); r != nil {
				r.Finish(50)
			}
		}()
	}
	wg.Wait()
}

