package traffic

import (
	"context"
	"errors"
	"math/rand/v2"
	"time"

	"relay/internal/llm"
)

// Policy says whether, when and how often to retry a failed model call.
type Policy struct {
	MaxRetries int           // retries after the first attempt
	Base       time.Duration // first backoff step
	Cap        time.Duration // largest backoff step
	Jitter     bool          // randomise waits so clients don't retry in lockstep
	UseHint    bool          // wait as long as the provider's retry-after says
	MinAttempt time.Duration // an attempt needs at least this long to be worth starting

	// Test hooks; nil means real randomness, clock and sleep.
	Rand  func() float64
	Now   func() time.Time
	Sleep func(context.Context, time.Duration) error
}

// DefaultPolicy is the real policy (DESIGN §5). MinAttempt is about the
// fastest first token the probe saw (178-220 ms).
func DefaultPolicy() Policy {
	return Policy{MaxRetries: 2, Base: 500 * time.Millisecond, Cap: 8 * time.Second,
		Jitter: true, UseHint: true, MinAttempt: 250 * time.Millisecond}
}

// NaivePolicy is the deliberately bad policy for the comparison run:
// fixed 1 s waits, no jitter, retry hint ignored. Same retry count, so
// only the timing differs.
func NaivePolicy() Policy {
	return Policy{MaxRetries: 2, Base: time.Second, Cap: time.Second}
}

// Retryable: only failures that may go away by themselves. A 4xx other
// than 429 means our request is wrong and will fail again; a cancelled
// caller has stopped listening.
func Retryable(err error) bool {
	var (
		rl *llm.RateLimitError
		se *llm.ServerError
		te *llm.TimeoutError
		ce *llm.ConnError
	)
	return errors.As(err, &rl) || errors.As(err, &se) || errors.As(err, &te) || errors.As(err, &ce)
}

// Delay is how long to wait before retry number `retry` (1, 2, ...).
//   - Provider hint (UseHint): wait the hint, plus up to Base of jitter so
//     everyone told "2 s" does not come back in the same millisecond.
//   - Otherwise exponential backoff Base*2^(retry-1), capped; with Jitter
//     it is "full jitter": a random wait between 0 and that step.
func (p Policy) Delay(retry int, err error) time.Duration {
	var rl *llm.RateLimitError
	if p.UseHint && errors.As(err, &rl) && rl.RetryAfter > 0 {
		if p.Jitter {
			return rl.RetryAfter + time.Duration(p.rand()*float64(p.Base))
		}
		return rl.RetryAfter
	}
	step := p.Base << (retry - 1)
	if step > p.Cap || step <= 0 { // <= 0 guards shift overflow
		step = p.Cap
	}
	if p.Jitter {
		return time.Duration(p.rand() * float64(step))
	}
	return step
}

// Stats describe what retrying cost one call, for results.csv.
type Stats struct {
	Retries     int           // attempts after the first
	RateLimited int           // 429s seen
	Backoff     time.Duration // total time spent waiting between attempts
}

// Do runs call, retrying per the policy. It stops when the call succeeds,
// the error is not retryable, retries run out, or the wait plus a minimal
// attempt would overrun ctx's deadline (a late answer is a lost answer).
// It returns the last error, not the backoff's.
func Do[T any](ctx context.Context, p Policy, call func(context.Context) (T, error)) (T, Stats, error) {
	var st Stats
	for attempt := 0; ; attempt++ {
		v, err := call(ctx)
		if err == nil {
			return v, st, nil
		}
		var rl *llm.RateLimitError
		if errors.As(err, &rl) {
			st.RateLimited++
		}
		if attempt >= p.MaxRetries || !Retryable(err) || ctx.Err() != nil {
			return v, st, err
		}
		d := p.Delay(attempt+1, err)
		if dl, ok := ctx.Deadline(); ok && p.now().Add(d+p.MinAttempt).After(dl) {
			return v, st, err
		}
		if p.sleep(ctx, d) != nil {
			return v, st, err
		}
		st.Retries++
		st.Backoff += d
	}
}

func (p Policy) rand() float64 {
	if p.Rand != nil {
		return p.Rand()
	}
	return rand.Float64()
}

func (p Policy) now() time.Time {
	if p.Now != nil {
		return p.Now()
	}
	return time.Now()
}

func (p Policy) sleep(ctx context.Context, d time.Duration) error {
	if p.Sleep != nil {
		return p.Sleep(ctx, d)
	}
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-t.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

package traffic

import (
	"context"
	"errors"
	"fmt"
	"testing"
	"time"

	"relay/internal/llm"
)

var (
	errRL     = &llm.RateLimitError{RetryAfter: 2 * time.Second}
	errRLNoHint = &llm.RateLimitError{}
	err5xx    = &llm.ServerError{Status: 503}
	err4xx    = &llm.ClientError{Status: 400}
	errTO     = &llm.TimeoutError{Phase: "first_token"}
	errConn   = &llm.ConnError{Err: errors.New("reset")}
)

func TestRetryable(t *testing.T) {
	for err, want := range map[error]bool{
		errRL: true, err5xx: true, errTO: true, errConn: true,
		err4xx: false, context.Canceled: false, errors.New("other"): false,
		fmt.Errorf("wrapped: %w", err5xx): true,
	} {
		if Retryable(err) != want {
			t.Errorf("Retryable(%v) = %v, want %v", err, !want, want)
		}
	}
}

func TestDelay(t *testing.T) {
	half := func() float64 { return 0.5 }
	p := DefaultPolicy()
	p.Rand = half
	tests := []struct {
		name  string
		p     Policy
		retry int
		err   error
		want  time.Duration
	}{
		{"hint plus jitter", p, 1, errRL, 2*time.Second + 250*time.Millisecond},
		{"429 without hint backs off", p, 1, errRLNoHint, 250 * time.Millisecond},
		{"full jitter retry 1", p, 1, err5xx, 250 * time.Millisecond},   // 0.5 * 500ms
		{"full jitter retry 2", p, 2, err5xx, 500 * time.Millisecond},   // 0.5 * 1s
		{"capped", p, 10, err5xx, 4 * time.Second},                      // 0.5 * 8s cap
		{"naive ignores hint", NaivePolicy(), 1, errRL, time.Second},
		{"naive is fixed", NaivePolicy(), 2, err5xx, time.Second},
	}
	for _, tt := range tests {
		if got := tt.p.Delay(tt.retry, tt.err); got != tt.want {
			t.Errorf("%s: %v, want %v", tt.name, got, tt.want)
		}
	}
}

// fakeTime lets Do's sleeps advance a clock instantly.
func fakeTime(p *Policy) *[]time.Duration {
	now := time.Unix(1_800_000_000, 0)
	var slept []time.Duration
	p.Now = func() time.Time { return now }
	p.Sleep = func(_ context.Context, d time.Duration) error { slept = append(slept, d); now = now.Add(d); return nil }
	p.Rand = func() float64 { return 0.5 }
	return &slept
}

// script returns a call that fails with errs in order, then succeeds.
func script(errs ...error) (func(context.Context) (string, error), *int) {
	calls := 0
	return func(context.Context) (string, error) {
		calls++
		if calls <= len(errs) {
			return "", errs[calls-1]
		}
		return "answer", nil
	}, &calls
}

func TestDoRetriesThenSucceeds(t *testing.T) {
	p := DefaultPolicy()
	slept := fakeTime(&p)
	call, calls := script(errRL, err5xx)
	v, st, err := Do(context.Background(), p, call)
	if err != nil || v != "answer" || *calls != 3 {
		t.Fatalf("v=%q err=%v calls=%d", v, err, *calls)
	}
	if st.Retries != 2 || st.RateLimited != 1 || st.Backoff != 2250*time.Millisecond+500*time.Millisecond {
		t.Errorf("stats %+v, slept %v", st, *slept)
	}
}

func TestDoGivesUpAfterMaxRetries(t *testing.T) {
	p := DefaultPolicy()
	fakeTime(&p)
	call, calls := script(err5xx, err5xx, err5xx, err5xx)
	_, st, err := Do(context.Background(), p, call)
	if !errors.Is(err, err5xx) || *calls != 3 || st.Retries != 2 {
		t.Errorf("err=%v calls=%d stats=%+v", err, *calls, st)
	}
}

func TestDoNeverRetriesClientErrors(t *testing.T) {
	p := DefaultPolicy()
	fakeTime(&p)
	call, calls := script(err4xx)
	if _, _, err := Do(context.Background(), p, call); !errors.Is(err, err4xx) || *calls != 1 {
		t.Errorf("err=%v calls=%d", err, *calls)
	}
}

func TestDoStopsWhenDeadlineWouldPass(t *testing.T) {
	p := DefaultPolicy()
	slept := fakeTime(&p)
	// 2s left: a 2.25s hinted wait cannot fit, so no retry is attempted.
	ctx, cancel := context.WithDeadline(context.Background(), p.Now().Add(2*time.Second))
	defer cancel()
	call, calls := script(errRL)
	_, st, err := Do(ctx, p, call)
	if !errors.Is(err, errRL) || *calls != 1 || len(*slept) != 0 || st.RateLimited != 1 {
		t.Errorf("err=%v calls=%d slept=%v", err, *calls, *slept)
	}
}

func TestDoStopsIfCallerCancelsDuringBackoff(t *testing.T) {
	p := DefaultPolicy()
	p.Sleep = func(context.Context, time.Duration) error { return context.Canceled }
	call, calls := script(err5xx)
	if _, _, err := Do(context.Background(), p, call); !errors.Is(err, err5xx) || *calls != 1 {
		t.Errorf("want the call's error after a cancelled backoff, got %v (calls=%d)", err, *calls)
	}
}

package traffic

import (
	"container/list"
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"relay/internal/bucket"
)

// Level is a rung of the degradation ladder (DESIGN §5). Each rung gives
// less; none gives something wrong.
type Level int

const (
	L0Full          Level = iota // full pipeline
	L1Lite                       // fewer chunks, no redraft (verify failure => refuse)
	L2Busy                       // "busy, try again in N seconds", N from the limiter
	L3RetrievalOnly              // daily budget gone: cited passages, no model call
)

func (l Level) String() string { return [...]string{"L0", "L1", "L2", "L3"}[l] }

var (
	ErrQueueFull = errors.New("queue full")
	ErrTooLarge  = errors.New("request larger than the token limit")
)

// AdmissionConfig holds the knobs the burst and overload runs tune.
type AdmissionConfig struct {
	MaxQueue int           // waiting requests beyond this get L2 at once
	Service  time.Duration // expected model time once a call starts
}

// Decision is what admission chose for one arriving request.
type Decision struct {
	Level    Level
	RetryIn  time.Duration // L2 only: when to try again, from the limiter's view
	Wait     time.Duration // estimated queue wait at arrival
	QueueLen int           // requests waiting at arrival (results.csv)
	Reason   string
}

// Admission is one FIFO queue in front of the limiter, plus the ladder.
type Admission struct {
	cfg AdmissionConfig
	lim *Limiter
	now func() time.Time

	mu           sync.Mutex
	queue        *list.List // of *waiter, front = next to run
	queuedTokens int        // tokens of everyone waiting, for estimates

	kick chan struct{} // wakes the dispatcher when the queue changes
	stop chan struct{}
}

type waiter struct {
	tokens int
	ready  chan *Reservation // buffered 1; nil reservation = can never fit
	elem   *list.Element     // nil once the waiter has left the queue
}

// NewAdmission starts the dispatcher; call Close when done.
func NewAdmission(lim *Limiter, cfg AdmissionConfig, now func() time.Time) *Admission {
	if now == nil {
		now = time.Now
	}
	a := &Admission{cfg: cfg, lim: lim, now: now, queue: list.New(),
		kick: make(chan struct{}, 1), stop: make(chan struct{})}
	go a.dispatch()
	return a
}

func (a *Admission) Close() { close(a.stop) }

// Decide picks the rung for a request arriving now that must finish by
// deadline. fullTokens/liteTokens are its L0 and L1 estimates.
//
// The wait estimate is the limiter's: how long until this request AND
// everyone queued ahead of it fit in the buckets. It then takes the best
// rung that still finishes in time; it does not queue a request that
// would only time out in the queue.
func (a *Admission) Decide(fullTokens, liteTokens int, deadline time.Time) Decision {
	a.mu.Lock()
	n, ahead := a.queue.Len(), a.queuedTokens
	a.mu.Unlock()

	left := deadline.Sub(a.now())
	fits := func(wait time.Duration) bool { return wait != bucket.Never && wait+a.cfg.Service <= left }

	waitLite, why := a.lim.Wait(n+1, ahead+liteTokens)
	d := Decision{QueueLen: n, Wait: waitLite}
	switch {
	case waitLite == bucket.Never:
		d.Level, d.Reason = L3RetrievalOnly, "request can never fit the token limit"
		return d
	case why == ByDay && !fits(waitLite):
		d.Level, d.Reason = L3RetrievalOnly, "daily budget exhausted"
		return d
	case n >= a.cfg.MaxQueue:
		d.Level, d.RetryIn, d.Reason = L2Busy, waitLite, "queue full"
		return d
	}

	if waitFull, _ := a.lim.Wait(n+1, ahead+fullTokens); fits(waitFull) {
		d.Level, d.Wait, d.Reason = L0Full, waitFull, "fits"
		return d
	}
	if fits(waitLite) {
		d.Level, d.Reason = L1Lite, "only the lighter answer fits in time"
		return d
	}
	d.Level, d.RetryIn, d.Reason = L2Busy, waitLite, fmt.Sprintf("would wait %s (%s limit)", waitLite.Round(time.Millisecond), why)
	return d
}

// Acquire joins the back of the queue and returns once the limiter has
// reserved room for `tokens`. If ctx ends first (the person gave up) the
// request leaves the queue at once, so it never blocks anyone behind it.
func (a *Admission) Acquire(ctx context.Context, tokens int) (*Reservation, error) {
	w := &waiter{tokens: tokens, ready: make(chan *Reservation, 1)}
	a.mu.Lock()
	if a.queue.Len() >= a.cfg.MaxQueue {
		a.mu.Unlock()
		return nil, ErrQueueFull
	}
	w.elem = a.queue.PushBack(w)
	a.queuedTokens += tokens
	a.mu.Unlock()
	a.wake()

	select {
	case r := <-w.ready:
		if r == nil {
			return nil, ErrTooLarge
		}
		return r, nil
	case <-ctx.Done():
		a.mu.Lock()
		if w.elem != nil {
			a.leave(w)
		}
		a.mu.Unlock()
		// Granted in the same instant we gave up: hand the room back.
		select {
		case r := <-w.ready:
			if r != nil {
				r.Cancel()
			}
		default:
		}
		a.wake()
		return nil, ctx.Err()
	}
}

// QueueLen is the number of requests waiting.
func (a *Admission) QueueLen() int {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.queue.Len()
}

// dispatch serves the front of the queue: reserve if the limiter allows,
// otherwise sleep until it would, or until the queue changes.
func (a *Admission) dispatch() {
	for {
		a.mu.Lock()
		front := a.queue.Front()
		if front == nil {
			a.mu.Unlock()
			select {
			case <-a.kick:
				continue
			case <-a.stop:
				return
			}
		}
		w := front.Value.(*waiter)
		r, wait, _ := a.lim.TryReserve(w.tokens)
		if r != nil || wait == bucket.Never {
			a.leave(w)
			w.ready <- r // nil when it can never fit
			a.mu.Unlock()
			continue
		}
		a.mu.Unlock()

		t := time.NewTimer(wait)
		select {
		case <-t.C:
		case <-a.kick:
			t.Stop()
		case <-a.stop:
			t.Stop()
			return
		}
	}
}

// leave removes w from the queue. Caller holds a.mu.
func (a *Admission) leave(w *waiter) {
	a.queue.Remove(w.elem)
	a.queuedTokens -= w.tokens
	w.elem = nil
}

// wake nudges the dispatcher without blocking.
func (a *Admission) wake() {
	select {
	case a.kick <- struct{}{}:
	default:
	}
}

