package pipeline

import (
	"strings"

	"relay/internal/retrieve"
)

// filler are words people put around a question that say nothing about
// what is being asked. The tokenizer's stopwords are general English;
// these are specific to asking about papers.
var filler = map[string]bool{
	"please": true, "can": true, "could": true, "would": true, "you": true, "tell": true,
	"me": true, "i": true, "explain": true, "describe": true, "give": true, "want": true,
	"know": true, "about": true, "paper": true, "papers": true, "authors": true,
	"according": true, "say": true, "says": true, "said": true, "detail": true, "details": true,
}

// Rewrite turns a question into a search query by rules, no model
// (DESIGN §2 step 1): lowercase, split like the index does, drop
// stopwords and question filler, keep everything else, including numbers
// and technical terms. If nothing would be left, it keeps the tokens.
func Rewrite(question string) string {
	tokens := retrieve.Tokenize(question)
	var kept []string
	for _, t := range tokens {
		if !filler[t] {
			kept = append(kept, t)
		}
	}
	if len(kept) == 0 {
		kept = tokens
	}
	return strings.Join(kept, " ")
}

package pipeline

import (
	"fmt"
	"strings"

	"relay/internal/corpus"
	"relay/internal/llm"
)

// systemPrompt states the rules Verify will check, so a model that
// follows them passes.
const systemPrompt = `You answer questions about three research papers using ONLY the chunks given to you.
Rules:
- End every claim with the id of the chunk it comes from, in square brackets, e.g. [1706.03762v7#12].
- Include at least one exact quote of three or more words, copied word for word from a chunk, in double quotes, followed by that chunk's id.
- Do not add anything that is not in the chunks.
- If the chunks do not answer the question, reply exactly: ` + RefusalText + `
- Use at most four sentences.`

// Messages builds the draft request. Each chunk is one line,
// "[<id>] <text>": the format the stand-in reads (internal/standin).
func Messages(question string, chunks []corpus.Chunk) []llm.Message {
	var b strings.Builder
	fmt.Fprintf(&b, "Question: %s\n\nChunks:\n", question)
	for _, c := range chunks {
		fmt.Fprintf(&b, "[%s] %s\n", c.ID, c.Text)
	}
	return []llm.Message{
		{Role: "system", Content: systemPrompt},
		{Role: "user", Content: b.String()},
	}
}

// Redraft asks once more, naming exactly what failed verification.
func Redraft(msgs []llm.Message, draft string, problems []string) []llm.Message {
	out := append([]llm.Message(nil), msgs...)
	return append(out,
		llm.Message{Role: "assistant", Content: draft},
		llm.Message{Role: "user", Content: "Your answer failed these checks:\n- " + strings.Join(problems, "\n- ") +
			"\nRewrite it following the rules. Quote only text that appears exactly in the chunks."},
	)
}

// Token estimate without a tokenizer, calibrated in the probe: about 72
// tokens of chat overhead plus one token per 5 characters (DECISIONS D9).
// The limiter settles the difference once real usage is known.
const (
	overheadTokens = 72
	charsPerToken  = 5
)

func estimateTokens(msgs []llm.Message) int {
	n := overheadTokens
	for _, m := range msgs {
		n += len(m.Content) / charsPerToken
	}
	return n
}

package pipeline

import (
	"regexp"
	"strings"
	"testing"

	"relay/internal/corpus"
)

func TestRewrite(t *testing.T) {
	tests := map[string]string{
		"Can you please explain why the Transformer scales dot products?":   "transformer scales dot products",
		"According to the paper, what frame rate does Mimi use (12.5 Hz?)": "frame rate mimi use 12 5 hz",
		"Tell me about it":         "tell me about it"[0:0] + "tell me", // all filler: fall back to tokens
		"What is the ratio loss?":  "ratio loss",
		"Does H-Net NOT use BPE?":  "h net not use bpe",
	}
	for in, want := range tests {
		if in == "Tell me about it" {
			want = "tell me about" // stopword "it" removed by Tokenize; filler kept as last resort
		}
		if got := Rewrite(in); got != want {
			t.Errorf("Rewrite(%q) = %q, want %q", in, got, want)
		}
	}
}

// The stand-in recognises chunk lines with this pattern; the prompt must
// produce lines it can read.
var standinChunkLine = regexp.MustCompile(`^\[([^\]\s]+#\d+)\]\s+(.+)$`)

func TestMessagesRenderOneChunkPerLine(t *testing.T) {
	cs := []corpus.Chunk{{ID: "1706.03762v7#3", Text: "alpha beta"}, {ID: "2410.00037v1#40", Text: "gamma"}}
	msgs := Messages("Why?", cs)
	if len(msgs) != 2 || msgs[0].Role != "system" || !strings.Contains(msgs[0].Content, RefusalText) {
		t.Fatalf("messages: %+v", msgs)
	}
	var found []string
	for _, line := range strings.Split(msgs[1].Content, "\n") {
		if m := standinChunkLine.FindStringSubmatch(line); m != nil {
			found = append(found, m[1])
		}
	}
	if len(found) != 2 || found[0] != cs[0].ID || found[1] != cs[1].ID {
		t.Errorf("chunk lines found: %v", found)
	}
}

func TestRedraftKeepsHistoryAndNamesProblems(t *testing.T) {
	msgs := Messages("Why?", nil)
	out := Redraft(msgs, "bad draft", []string{"quote not found"})
	if len(out) != 4 || out[2].Content != "bad draft" || !strings.Contains(out[3].Content, "quote not found") {
		t.Errorf("redraft: %+v", out)
	}
	if len(msgs) != 2 {
		t.Error("Redraft must not modify the original messages")
	}
}

func TestEstimateTokensMatchesProbeCalibration(t *testing.T) {
	// The probe's "Say ok." prompt was 74 tokens; with our system prompt
	// excluded, the estimate for that one message should be close.
	got := estimateTokens([]llmMessage{{Role: "user", Content: "Say ok."}})
	if got < 72 || got > 76 {
		t.Errorf("estimate %d, probe measured 74", got)
	}
}

