package pipeline

import (
	"context"
	"errors"
	"fmt"
	"math"
	"strings"
	"time"

	"relay/internal/corpus"
	"relay/internal/llm"
	"relay/internal/retrieve"
	"relay/internal/traffic"
)

// Setting is one retrieval configuration (DESIGN §3, Table 3).
type Setting struct {
	Name       string
	ChunkWords int
	Overlap    int
	K          int // chunks fetched
}

// Settings are the three starting configurations; no re-ranker.
var Settings = []Setting{
	{Name: "R1", ChunkWords: 150, Overlap: 30, K: 6},
	{Name: "R2", ChunkWords: 300, Overlap: 60, K: 4},
	{Name: "R3", ChunkWords: 300, Overlap: 60, K: 2},
}

func SettingByName(name string) (Setting, error) {
	for _, s := range Settings {
		if s.Name == name {
			return s, nil
		}
	}
	return Setting{}, fmt.Errorf("unknown retrieval setting %q", name)
}

// Config holds the pipeline's knobs. Threshold and the deadlines are TBD
// in DESIGN; these defaults are starting points to be tuned on the dev
// half of the eval and the probe.
type Config struct {
	Model             string
	MaxOutput         int     // max_completion_tokens: room for hidden reasoning + answer (D7)
	Threshold         float64 // T: refuse without a model call if the top Norm is below it
	LiteK             int     // chunks used at L1
	FirstTokenTimeout time.Duration
	Retry             traffic.Policy
}

func DefaultConfig() Config {
	return Config{
		Model:             "openai/gpt-oss-20b",
		MaxOutput:         600,
		Threshold:         0.2,
		LiteK:             2,
		FirstTokenTimeout: 3 * time.Second, // probe max under burst was 1.26 s
		Retry:             traffic.DefaultPolicy(),
	}
}

// Fixed replies. None of them states anything about the papers that was
// not verified, so none can be wrong.
const (
	CouldNotVerify = "I could not verify an answer from the papers, so I won't guess."
	TimeoutText    = "Sorry, this took too long. Please try again."
	ErrorText      = "Something went wrong on our side. Please try again."
)

// Pipeline answers questions. Safe for concurrent use.
type Pipeline struct {
	cfg     Config
	setting Setting
	ix      *retrieve.Index
	client  llm.Client
	lim     *traffic.Limiter
	adm     *traffic.Admission
	now     func() time.Time
}

func New(cfg Config, s Setting, chunks []corpus.Chunk, client llm.Client, lim *traffic.Limiter, adm *traffic.Admission) *Pipeline {
	return &Pipeline{cfg: cfg, setting: s, ix: retrieve.NewIndex(chunks), client: client, lim: lim, adm: adm, now: time.Now}
}

// Reply is what the person sees plus everything results.csv needs.
type Reply struct {
	Text    string
	Status  string        // ok, rate_limited, timeout, error
	Level   traffic.Level // ladder rung
	Refused bool          // "the papers do not say" or "could not verify"
	Cited   []string      // chunk ids behind the answer
	Detail  string        // why it ended this way

	TopNorm   float64 // best retrieval score, for tuning T
	Drafts    int
	TokensIn  int
	TokensOut int
	Retries   int
	N429      int
	QueueLen  int

	QueueWait       time.Duration // time waiting for the limiter
	ModelTime       time.Duration // time inside model calls
	ModelFirstToken time.Time     // first token from the model (first draft)
	Released        time.Time     // when the reply was shown: the first token the person sees
}

// Answer runs the five steps for one question that must be answered by
// deadline (the person's patience).
func (p *Pipeline) Answer(ctx context.Context, question string, deadline time.Time) (rep Reply) {
	rep.Status = "ok"
	defer func() { rep.Released = p.now() }()
	ctx, cancel := context.WithDeadline(ctx, deadline)
	defer cancel()

	// 1-2. Rewrite and retrieve (the tool call: our own BM25).
	hits := p.ix.Search(Rewrite(question), p.setting.K)

	// 3. Decide: weak retrieval means the papers probably don't say.
	if len(hits) > 0 {
		rep.TopNorm = hits[0].Norm
	}
	if rep.TopNorm < p.cfg.Threshold {
		rep.Text, rep.Refused = RefusalText, true
		rep.Detail = fmt.Sprintf("top retrieval score %.3f below threshold %.3f", rep.TopNorm, p.cfg.Threshold)
		return rep
	}
	chunks := chunksOf(hits)
	lite := chunks[:min(p.cfg.LiteK, len(chunks))]

	// Admission picks the ladder rung before any token is spent.
	d := p.adm.Decide(
		estimateTokens(Messages(question, chunks))+p.cfg.MaxOutput,
		estimateTokens(Messages(question, lite))+p.cfg.MaxOutput,
		deadline)
	rep.Level, rep.QueueLen, rep.Detail = d.Level, d.QueueLen, d.Reason
	switch d.Level {
	case traffic.L3RetrievalOnly:
		rep.Status, rep.Text = "rate_limited", passages(hits)
		return rep
	case traffic.L2Busy:
		rep.Status, rep.Text = "rate_limited", busy(d.RetryIn)
		return rep
	case traffic.L1Lite:
		chunks = lite
	}

	// 4-5. Draft, verify, redraft at most once (never at L1).
	maxDrafts := 2
	if d.Level == traffic.L1Lite {
		maxDrafts = 1
	}
	msgs := Messages(question, chunks)
	for {
		text, err := p.draft(ctx, msgs, &rep)
		if err != nil {
			rep.Status, rep.Detail = statusOf(err), err.Error()
			rep.Text = map[string]string{"timeout": TimeoutText, "rate_limited": busy(0), "error": ErrorText}[rep.Status]
			return rep
		}
		rep.Drafts++
		v := Verify(text, chunks)
		switch {
		case v.OK && v.Refusal:
			rep.Text, rep.Refused, rep.Detail = RefusalText, true, "model found no answer in the chunks"
			return rep
		case v.OK:
			rep.Text, rep.Cited, rep.Detail = renderCitations(text, chunks), v.Cited, "verified"
			return rep
		case rep.Drafts >= maxDrafts:
			rep.Text, rep.Refused = CouldNotVerify, true
			rep.Detail = "verify failed: " + strings.Join(v.Problems, "; ")
			return rep
		}
		msgs = Redraft(msgs, text, v.Problems)
	}
}

// draft makes one model call through the queue, limiter and retry policy.
// Every attempt, including retries, waits its turn in the queue.
func (p *Pipeline) draft(ctx context.Context, msgs []llm.Message, rep *Reply) (string, error) {
	req := llm.Request{
		Model: p.cfg.Model, Messages: msgs, MaxTokens: p.cfg.MaxOutput,
		ReasoningEffort: "low", FirstTokenTimeout: p.cfg.FirstTokenTimeout,
	}
	tokens := estimateTokens(msgs) + p.cfg.MaxOutput

	resp, st, err := traffic.Do(ctx, p.cfg.Retry, func(ctx context.Context) (*llm.Response, error) {
		queued := p.now()
		res, err := p.adm.Acquire(ctx, tokens)
		rep.QueueWait += p.now().Sub(queued)
		if err != nil {
			return nil, err
		}
		resp, err := p.client.Complete(ctx, req)
		p.settle(res, resp, err)
		p.timeModel(resp, rep)
		return resp, err
	})
	rep.Retries += st.Retries
	rep.N429 += st.RateLimited
	if err != nil {
		return "", err
	}
	rep.TokensIn += resp.TokensIn
	rep.TokensOut += resp.TokensOut
	return resp.Text, nil
}

// settle tells the limiter what happened. This is where provider headers
// correct our counts and a 429's retry hint pauses everyone.
func (p *Pipeline) settle(res *traffic.Reservation, resp *llm.Response, err error) {
	var rl *llm.RateLimitError
	switch {
	case errors.As(err, &rl):
		p.lim.Observe(rl.Limits)
		p.lim.PauseFor(rl.RetryAfter)
		res.Cancel() // refused calls did not run
	case err == nil:
		p.lim.Observe(resp.Limits)
		res.Finish(resp.TokensIn + resp.TokensOut)
	default:
		if resp != nil {
			p.lim.Observe(resp.Limits)
		}
		res.Finish(0) // it was sent; actual tokens unknown
	}
}

// timeModel adds this attempt's time inside the model call.
func (p *Pipeline) timeModel(resp *llm.Response, rep *Reply) {
	if resp == nil || resp.Sent.IsZero() {
		return
	}
	end := resp.Done
	if end.IsZero() {
		end = p.now()
	}
	rep.ModelTime += end.Sub(resp.Sent)
	if rep.ModelFirstToken.IsZero() && !resp.FirstToken.IsZero() {
		rep.ModelFirstToken = resp.FirstToken
	}
}

// statusOf maps the final error to the brief's status values.
func statusOf(err error) string {
	var (
		te *llm.TimeoutError
		rl *llm.RateLimitError
	)
	switch {
	case errors.As(err, &te), errors.Is(err, context.DeadlineExceeded):
		return "timeout"
	case errors.As(err, &rl), errors.Is(err, traffic.ErrQueueFull):
		return "rate_limited"
	default:
		return "error"
	}
}

func chunksOf(hits []retrieve.Hit) []corpus.Chunk {
	cs := make([]corpus.Chunk, len(hits))
	for i, h := range hits {
		cs[i] = h.Chunk
	}
	return cs
}

// renderCitations swaps chunk ids for readable citations:
// [1706.03762v7#9] -> [1706.03762v7, §3.2.1, p.4].
func renderCitations(text string, chunks []corpus.Chunk) string {
	byID := make(map[string]corpus.Chunk, len(chunks))
	for _, c := range chunks {
		byID[c.ID] = c
	}
	return citeRe.ReplaceAllStringFunc(text, func(m string) string {
		if c, ok := byID[m[1:len(m)-1]]; ok {
			return c.Citation()
		}
		return m
	})
}

// busy is the L2 reply. N comes from the limiter, never a guess.
func busy(retryIn time.Duration) string {
	if retryIn <= 0 {
		return "We're busy right now. Please try again shortly."
	}
	return fmt.Sprintf("We're busy right now. Please try again in %d seconds.", int(math.Ceil(retryIn.Seconds())))
}

// passages is the L3 reply: the best matching text from the papers with
// citations, no model call. It quotes only the papers, so it cannot be
// wrong; it may simply not answer the question.
func passages(hits []retrieve.Hit) string {
	const show, words = 3, 40
	var b strings.Builder
	b.WriteString("Our daily model budget is used up, so I can't write an answer. These passages from the papers best match your question:\n")
	for i, h := range hits[:min(show, len(hits))] {
		ws := strings.Fields(h.Chunk.Text)
		excerpt := strings.Join(ws[:min(words, len(ws))], " ")
		if len(ws) > words {
			excerpt += " …"
		}
		fmt.Fprintf(&b, "\n%d. \"%s\" %s", i+1, excerpt, h.Chunk.Citation())
	}
	return b.String()
}

package pipeline

import (
	"context"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"relay/internal/corpus"
	"relay/internal/llm"
	"relay/internal/standin"
	"relay/internal/traffic"
)

var lib = []corpus.Chunk{
	{ID: "1706.03762v7#9", Paper: "1706.03762", Version: 7, Section: "3.2.1", PageStart: 4, PageEnd: 4,
		Text: "We suspect that for large values of dk the dot products grow large in magnitude pushing the softmax function into regions where it has extremely small gradients"},
	{ID: "2410.00037v1#40", Paper: "2410.00037", Version: 1, Section: "3.3.1", PageStart: 10, PageEnd: 10,
		Text: "Mimi encoder projects a 24kHz waveform to a latent representation of 12.5 frames per second"},
	{ID: "2507.07955v2#3", Paper: "2507.07955", Version: 2, Section: "2.2.1", PageStart: 6, PageEnd: 6,
		Text: "The routing module implements this intuition through cosine similarity between adjacent encoder outputs"},
}

const (
	question = "Why do the dot products get scaled before the softmax?"
	good     = `They grow large: "the dot products grow large in magnitude" [1706.03762v7#9].`
	bad      = `They shrink: "the dot products shrink" [1706.03762v7#9].`
)

// fakeClient returns scripted results in order and counts calls.
type fakeClient struct {
	mu      sync.Mutex
	script  []any // string (answer) or error
	calls   int
	lastMsg []llm.Message
}

func (f *fakeClient) Complete(_ context.Context, req llm.Request) (*llm.Response, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.lastMsg = req.Messages
	step := f.script[min(f.calls, len(f.script)-1)]
	f.calls++
	now := time.Now()
	if err, ok := step.(error); ok {
		return &llm.Response{Sent: now}, err
	}
	return &llm.Response{Text: step.(string), TokensIn: 500, TokensOut: 80, Sent: now, FirstToken: now, Done: now,
		Limits: llm.RateLimits{RemainingRequests: -1, RemainingTokens: -1}}, nil
}

func newPipeline(t *testing.T, client llm.Client, l traffic.Limits) (*Pipeline, *traffic.Limiter) {
	t.Helper()
	cfg := DefaultConfig()
	cfg.Threshold = 0.1
	cfg.Retry.Sleep = func(context.Context, time.Duration) error { return nil } // no real backoff in tests
	lim := traffic.NewLimiter(l, nil)
	adm := traffic.NewAdmission(lim, traffic.AdmissionConfig{MaxQueue: 10, Service: time.Second}, nil)
	t.Cleanup(adm.Close)
	return New(cfg, Settings[1], lib, client, lim, adm), lim
}

func ask(p *Pipeline, q string) Reply {
	return p.Answer(context.Background(), q, time.Now().Add(10*time.Second))
}

func TestVerifiedAnswerShowsReadableCitation(t *testing.T) {
	c := &fakeClient{script: []any{good}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	r := ask(p, question)
	if r.Status != "ok" || r.Level != traffic.L0Full || r.Refused || r.Drafts != 1 {
		t.Fatalf("reply %+v", r)
	}
	if !strings.Contains(r.Text, "[1706.03762v7, §3.2.1, p.4]") || strings.Contains(r.Text, "#9]") {
		t.Errorf("citation not rendered: %q", r.Text)
	}
	if r.TokensIn != 500 || r.TokensOut != 80 || r.Released.IsZero() {
		t.Errorf("accounting: %+v", r)
	}
}

func TestOffTopicRefusedWithoutModelCall(t *testing.T) {
	c := &fakeClient{script: []any{good}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	r := ask(p, "What is the time complexity of Dijkstra's algorithm?")
	if !r.Refused || r.Text != RefusalText || c.calls != 0 {
		t.Errorf("reply %+v, model calls %d", r, c.calls)
	}
}

func TestRedraftOnceThenSucceed(t *testing.T) {
	c := &fakeClient{script: []any{bad, good}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	r := ask(p, question)
	if r.Status != "ok" || r.Drafts != 2 || r.Refused {
		t.Fatalf("reply %+v", r)
	}
	last := c.lastMsg[len(c.lastMsg)-1].Content
	if !strings.Contains(last, "not word for word") {
		t.Errorf("redraft prompt should name the failure: %q", last)
	}
}

func TestTwoBadDraftsRefuse(t *testing.T) {
	c := &fakeClient{script: []any{bad, bad, good}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	r := ask(p, question)
	if r.Text != CouldNotVerify || !r.Refused || r.Drafts != 2 || c.calls != 2 {
		t.Errorf("reply %+v calls %d", r, c.calls)
	}
}

func TestModelRefusalShowsOnlyRefusalSentence(t *testing.T) {
	c := &fakeClient{script: []any{"The papers do not say. But I think it is 42."}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	if r := ask(p, question); r.Text != RefusalText || !r.Refused {
		t.Errorf("reply %+v", r)
	}
}

func TestRateLimitRetriedAndPausesLimiter(t *testing.T) {
	c := &fakeClient{script: []any{&llm.RateLimitError{RetryAfter: 50 * time.Millisecond,
		Limits: llm.RateLimits{RemainingRequests: -1, RemainingTokens: -1}}, good}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	r := ask(p, question)
	if r.Status != "ok" || r.Retries != 1 || r.N429 != 1 {
		t.Errorf("reply %+v", r)
	}
	if r.QueueWait < 40*time.Millisecond {
		t.Errorf("the retry should have waited out the provider's pause in the queue, waited %v", r.QueueWait)
	}
}

func TestClientErrorIsNotRetried(t *testing.T) {
	c := &fakeClient{script: []any{&llm.ClientError{Status: 400}, good}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	if r := ask(p, question); r.Status != "error" || c.calls != 1 || r.Text != ErrorText {
		t.Errorf("reply %+v calls %d", r, c.calls)
	}
}

func TestDailyBudgetGoneGivesPassages(t *testing.T) {
	c := &fakeClient{script: []any{good}}
	p, lim := newPipeline(t, c, traffic.GroqFree)
	lim.Observe(llm.RateLimits{RemainingRequests: 0, RemainingTokens: -1})
	r := ask(p, question)
	if r.Level != traffic.L3RetrievalOnly || r.Status != "rate_limited" || c.calls != 0 || r.TokensIn != 0 {
		t.Fatalf("reply %+v calls %d", r, c.calls)
	}
	if !strings.Contains(r.Text, "[1706.03762v7, §3.2.1, p.4]") || !strings.Contains(r.Text, "dot products grow large") {
		t.Errorf("passages: %q", r.Text)
	}
}

func TestBusyWhenMinuteBudgetTooTight(t *testing.T) {
	c := &fakeClient{script: []any{good}}
	p, lim := newPipeline(t, c, traffic.GroqFree)
	lim.PauseFor(30 * time.Second)
	r := ask(p, question)
	if r.Level != traffic.L2Busy || r.Status != "rate_limited" || !strings.Contains(r.Text, "30 seconds") || c.calls != 0 {
		t.Errorf("reply %+v", r)
	}
}

func TestTimeoutStatus(t *testing.T) {
	c := &fakeClient{script: []any{&llm.TimeoutError{Phase: "first_token"}}}
	p, _ := newPipeline(t, c, traffic.GroqFree)
	if r := ask(p, question); r.Status != "timeout" || r.Text != TimeoutText {
		t.Errorf("reply %+v", r)
	}
}

// End to end through the real HTTP client and the stand-in server.
func TestAgainstStandIn(t *testing.T) {
	cfg := standin.Default()
	cfg.FirstTokenMS = []float64{5}
	cfg.OutputMSPerToken, cfg.LoadMSPerInFlight, cfg.RefusalMS = 0, 0, 0
	srv := httptest.NewServer(standin.New(cfg))
	defer srv.Close()

	p, _ := newPipeline(t, llm.NewHTTP(srv.URL, ""), traffic.GroqFree)
	r := ask(p, question)
	if r.Status != "ok" || r.Refused || len(r.Cited) != 1 || r.TokensIn == 0 || r.ModelFirstToken.IsZero() {
		t.Fatalf("reply %+v", r)
	}
	if r.Released.Before(r.ModelFirstToken) {
		t.Error("buffered release cannot come before the model's first token")
	}
}

