// Package loadgen drives the pipeline with an open-loop schedule and
// records one results.csv row per request (DESIGN §6).
package loadgen

import (
	"math/rand/v2"
	"time"
)

// Phase is a stretch of time with a constant average arrival rate.
type Phase struct {
	PerMinute float64
	For       time.Duration
}

// Arrivals returns start offsets for every request, phase after phase.
// Gaps are exponential (a Poisson process): real traffic is bursty even
// at a steady average, and evenly spaced arrivals would flatter us. The
// seed makes a run repeatable.
func Arrivals(phases []Phase, seed uint64) []time.Duration {
	rng := rand.New(rand.NewPCG(seed, seed))
	var out []time.Duration
	var phaseStart time.Duration
	for _, ph := range phases {
		if ph.PerMinute > 0 {
			meanGap := float64(time.Minute) / ph.PerMinute
			t := time.Duration(rng.ExpFloat64() * meanGap)
			for t < ph.For {
				out = append(out, phaseStart+t)
				t += time.Duration(rng.ExpFloat64() * meanGap)
			}
		}
		phaseStart += ph.For
	}
	return out
}

// Burst is n requests at one instant, after `at`: the "something broke,
// everyone asks at once" shape the brief describes.
func Burst(at time.Duration, n int) []time.Duration {
	out := make([]time.Duration, n)
	for i := range out {
		out[i] = at
	}
	return out
}

package loadgen

import (
	"context"
	"fmt"
	"sort"
	"sync"
	"time"

	"relay/internal/pipeline"
	"relay/internal/results"
)

// Asker is the pipeline as the generator sees it.
type Asker interface {
	Answer(ctx context.Context, question string, deadline time.Time) pipeline.Reply
}

// Job is one scheduled request.
type Job struct {
	Offset     time.Duration // from the run's start
	QuestionID string
	Question   string
}

// Run describes one scenario run.
type Run struct {
	Scenario string
	Source   string // "real" or "stand-in"
	Setting  string // retrieval setting name
	Patience time.Duration
	Jobs     []Job

	// Grade, if set, fills answer_grade (eval rows only).
	Grade func(questionID string, r pipeline.Reply) string
}

// Summary is what the run reports at the end.
type Summary struct {
	Sent   int
	MaxLag time.Duration // worst start lateness: the lag check
}

// Execute starts every job at its scheduled time, whether or not earlier
// ones have finished (open loop), and writes one row per job. Latency is
// measured from the scheduled start, so time a request spends waiting
// because we are slow is counted against us, not hidden.
func (r Run) Execute(ctx context.Context, a Asker, w *results.Writer) (Summary, error) {
	jobs := append([]Job(nil), r.Jobs...)
	sort.SliceStable(jobs, func(i, j int) bool { return jobs[i].Offset < jobs[j].Offset })

	start := time.Now().Add(20 * time.Millisecond) // a moment to set up
	runID := start.UTC().Format("150405")
	var (
		wg      sync.WaitGroup
		mu      sync.Mutex
		maxLag  time.Duration
		werr    error
	)
	for i, job := range jobs {
		scheduled := start.Add(job.Offset)
		if d := time.Until(scheduled); d > 0 {
			select {
			case <-time.After(d):
			case <-ctx.Done():
				wg.Wait()
				return Summary{Sent: i, MaxLag: maxLag}, ctx.Err()
			}
		}
		lag := time.Since(scheduled)
		mu.Lock()
		maxLag = max(maxLag, lag)
		mu.Unlock()

		id := fmt.Sprintf("%s-%s-%s-%04d", r.Scenario, r.Setting, runID, i)
		wg.Add(1)
		go func() {
			defer wg.Done()
			rep := a.Answer(ctx, job.Question, scheduled.Add(r.Patience))
			row := r.row(id, job, scheduled, lag, rep)
			if err := w.Write(row); err != nil {
				mu.Lock()
				werr = err
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	return Summary{Sent: len(jobs), MaxLag: maxLag}, werr
}

// row maps a reply to the results.csv columns. The person's first token
// is when the verified reply was released (answers are buffered); a
// timeout or error shows them no answer, so first_token_ms is empty.
func (r Run) row(id string, job Job, scheduled time.Time, lag time.Duration, rep pipeline.Reply) results.Row {
	total := rep.Released.Sub(scheduled).Milliseconds()
	first := int64(-1)
	if rep.Status == "ok" || rep.Status == "rate_limited" {
		first = total
	}
	grade := ""
	if r.Grade != nil {
		grade = r.Grade(job.QuestionID, rep)
	}
	return results.Row{
		RequestID: id, Scenario: r.Scenario, Source: r.Source, Start: scheduled,
		FirstTokenMS: first, TotalMS: total, Status: rep.Status, Retries: rep.Retries,
		TokensIn: rep.TokensIn, TokensOut: rep.TokensOut, RetrievalSetting: r.Setting, AnswerGrade: grade,
		QuestionID: job.QuestionID, QueueWaitMS: rep.QueueWait.Milliseconds(), ModelMS: rep.ModelTime.Milliseconds(),
		QueueLenAtArrival: rep.QueueLen, LadderLevel: int(rep.Level), N429Seen: rep.N429,
		ErrorDetail: rep.Detail, StartLagMS: lag.Milliseconds(),
	}
}

package loadgen

import (
	"context"
	"os"
	"path/filepath"
	"strconv"
	"sync/atomic"
	"testing"
	"time"

	"relay/internal/pipeline"
	"relay/internal/results"
	"relay/internal/traffic"
)

func TestArrivalsRateAndRepeatability(t *testing.T) {
	phases := []Phase{{PerMinute: 600, For: time.Minute}, {PerMinute: 0, For: time.Minute}, {PerMinute: 60, For: time.Minute}}
	a := Arrivals(phases, 7)
	b := Arrivals(phases, 7)
	if len(a) != len(b) || a[10] != b[10] {
		t.Fatal("same seed must give the same schedule")
	}
	var first, quiet, third int
	for i, off := range a {
		if i > 0 && off < a[i-1] {
			t.Fatal("offsets must be sorted")
		}
		switch {
		case off < time.Minute:
			first++
		case off < 2*time.Minute:
			quiet++
		default:
			third++
		}
	}
	// Poisson counts: 600 ± ~3σ (σ≈24.5), 60 ± ~3σ (σ≈7.7).
	if first < 525 || first > 675 || quiet != 0 || third < 37 || third > 83 {
		t.Errorf("counts per phase: %d, %d, %d", first, quiet, third)
	}
}

// slowAsker takes `d` per answer and counts how many run at once.
type slowAsker struct {
	d             time.Duration
	inFlight, max atomic.Int32
}

func (s *slowAsker) Answer(ctx context.Context, q string, deadline time.Time) pipeline.Reply {
	n := s.inFlight.Add(1)
	for {
		m := s.max.Load()
		if n <= m || s.max.CompareAndSwap(m, n) {
			break
		}
	}
	time.Sleep(s.d)
	s.inFlight.Add(-1)
	return pipeline.Reply{Status: "ok", Released: time.Now(), Level: traffic.L1Lite, Drafts: 1}
}

func openWriter(t *testing.T) (*results.Writer, string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "results.csv")
	w, err := results.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { w.Close() })
	return w, path
}

func readRows(t *testing.T, path string) []map[string]string {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	rows, err := results.ReadAll(f)
	if err != nil {
		t.Fatal(err)
	}
	return rows
}

func TestOpenLoopDoesNotWaitForSlowAnswers(t *testing.T) {
	// 10 jobs 10 ms apart, each taking 100 ms. A closed loop would take
	// ~1 s and never overlap; an open loop overlaps them and starts each
	// on schedule.
	var jobs []Job
	for i := 0; i < 10; i++ {
		jobs = append(jobs, Job{Offset: time.Duration(i) * 10 * time.Millisecond, QuestionID: "q" + strconv.Itoa(i), Question: "?"})
	}
	a := &slowAsker{d: 100 * time.Millisecond}
	w, path := openWriter(t)
	start := time.Now()
	sum, err := Run{Scenario: "test", Source: "stand-in", Setting: "R2", Patience: time.Second, Jobs: jobs}.Execute(context.Background(), a, w)
	if err != nil {
		t.Fatal(err)
	}
	if took := time.Since(start); took > 400*time.Millisecond {
		t.Errorf("run took %v: requests waited for each other", took)
	}
	if a.max.Load() < 5 {
		t.Errorf("max concurrent = %d, want overlap", a.max.Load())
	}
	if sum.Sent != 10 || sum.MaxLag > 20*time.Millisecond {
		t.Errorf("summary %+v: generator started requests late", sum)
	}

	rows := readRows(t, path)
	if len(rows) != 10 {
		t.Fatalf("%d rows", len(rows))
	}
	for _, r := range rows {
		total, _ := strconv.Atoi(r["total_ms"])
		if total < 95 || r["ladder_level"] != "1" || r["first_token_ms"] != r["total_ms"] {
			t.Errorf("row %v", r)
		}
	}
}

func TestLatencyCountsFromScheduledStart(t *testing.T) {
	// A reply released 300 ms after its scheduled start is 300 ms of
	// latency, whatever the generator did in between.
	r := Run{Scenario: "s", Source: "real", Setting: "R1"}
	sched := time.Now()
	row := r.row("id", Job{QuestionID: "q1"}, sched, 5*time.Millisecond,
		pipeline.Reply{Status: "timeout", Released: sched.Add(300 * time.Millisecond)})
	if row.TotalMS != 300 || row.FirstTokenMS != -1 || row.StartLagMS != 5 {
		t.Errorf("row %+v", row)
	}
}

func TestGradeOnlyWhenAsked(t *testing.T) {
	sched := time.Now()
	rep := pipeline.Reply{Status: "ok", Released: sched}
	plain := Run{Scenario: "s", Source: "real", Setting: "R1"}.row("a", Job{QuestionID: "q1"}, sched, 0, rep)
	graded := Run{Scenario: "eval", Source: "real", Setting: "R1",
		Grade: func(string, pipeline.Reply) string { return "correct" }}.row("b", Job{QuestionID: "q1"}, sched, 0, rep)
	if plain.AnswerGrade != "" || graded.AnswerGrade != "correct" {
		t.Errorf("plain %q graded %q", plain.AnswerGrade, graded.AnswerGrade)
	}
}

package main

import (
	"time"

	"relay/internal/loadgen"
	"relay/internal/standin"
	"relay/internal/traffic"
)

// scenario is one load shape plus the world it runs in.
//
// Rates come from the probe: TPM binds first, and at ~1.9K tokens per
// answer 8K TPM serves about 4 answers a minute. "Steady" sits under
// that, "overload" is 3x over it.
type scenario struct {
	arrivals func(seed uint64) []time.Duration
	provider func(*standin.Config) // how the stand-in behaves (ignored for real runs)
	limits   traffic.Limits         // what OUR limiter believes
	patience time.Duration          // how long a person waits before giving up
	eval     bool                   // closed loop over the questions, graded
	real     bool                   // allowed against real Groq (budget guard)
}

const patience = 20 * time.Second // DESIGN §5: TBD; starting guess, tested by the runs

var scenarios = map[string]scenario{
	// Eval: each question once, one at a time, graded. Generous patience
	// so the limiter may queue rather than refuse.
	"eval": {eval: true, real: true, limits: traffic.GroqFree, patience: 2 * time.Minute, provider: func(*standin.Config) {}},

	// Under capacity: 3 a minute for 5 minutes.
	"steady": {
		arrivals: func(s uint64) []time.Duration { return loadgen.Arrivals([]loadgen.Phase{{PerMinute: 3, For: 5 * time.Minute}}, s) },
		provider: func(*standin.Config) {}, limits: traffic.GroqFree, patience: patience, real: true,
	},

	// Steady background, then 20 people ask at the same instant at 1:00.
	"burst": {
		arrivals: func(s uint64) []time.Duration {
			return append(loadgen.Arrivals([]loadgen.Phase{{PerMinute: 3, For: 4 * time.Minute}}, s), loadgen.Burst(time.Minute, 20)...)
		},
		provider: func(*standin.Config) {}, limits: traffic.GroqFree, patience: patience,
	},

	// 3x capacity for 4 minutes, with some provider failures to retry.
	"overload": {
		arrivals: func(s uint64) []time.Duration { return loadgen.Arrivals([]loadgen.Phase{{PerMinute: 12, For: 4 * time.Minute}}, s) },
		provider: func(c *standin.Config) { c.ServerErrorRate, c.DropRate = 0.02, 0.01 },
		limits:   traffic.GroqFree, patience: patience,
	},

	// The provider halves its per-minute limits without telling us: our
	// limiter still believes 30 RPM / 8K TPM and must learn from headers
	// and 429s. The brief: limits "can change without notice".
	"halved": {
		arrivals: func(s uint64) []time.Duration { return loadgen.Arrivals([]loadgen.Phase{{PerMinute: 3, For: 4 * time.Minute}}, s) },
		provider: func(c *standin.Config) { c.RPM, c.TPM = 15, 4000 },
		limits:   traffic.GroqFree, patience: patience,
	},

	// The day's requests are gone at the provider; one trickles back every
	// 86.4 s. Our limiter starts unaware and learns from the first reply.
	"daily-exhausted": {
		arrivals: func(s uint64) []time.Duration { return loadgen.Arrivals([]loadgen.Phase{{PerMinute: 3, For: 3 * time.Minute}}, s) },
		provider: func(c *standin.Config) { c.StartRPD = 0 },
		limits:   traffic.GroqFree, patience: patience,
	},

	// Plumbing check only: a few seconds of load, for tests and smoke runs.
	"smoke": {
		arrivals: func(s uint64) []time.Duration { return loadgen.Arrivals([]loadgen.Phase{{PerMinute: 300, For: 2 * time.Second}}, s) },
		provider: func(*standin.Config) {}, limits: traffic.GroqFree, patience: patience,
	},
}

// Command loadgen runs one scenario and appends its rows to results.csv.
//
//	go run ./cmd/loadgen -scenario burst                       # stand-in (default)
//	go run ./cmd/loadgen -scenario halved -policy naive        # the naive-retry comparison
//	go run ./cmd/loadgen -scenario eval -source real -setting R1 -split dev
package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"math/rand/v2"
	"net"
	"net/http"
	"os"
	"sort"
	"strings"
	"time"

	"relay/internal/corpus"
	"relay/internal/eval"
	"relay/internal/llm"
	"relay/internal/loadgen"
	"relay/internal/pipeline"
	"relay/internal/results"
	"relay/internal/standin"
	"relay/internal/traffic"
)

const groqURL = "https://api.groq.com/openai/v1"

func main() {
	if err := run(os.Args[1:], os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "loadgen:", err)
		os.Exit(1)
	}
}

func run(args []string, out io.Writer) error {
	fs := flag.NewFlagSet("loadgen", flag.ContinueOnError)
	name := fs.String("scenario", "", "eval, steady, burst, overload, halved, daily-exhausted, smoke")
	source := fs.String("source", "stand-in", "stand-in or real")
	settingName := fs.String("setting", "R2", "retrieval setting")
	policyName := fs.String("policy", "default", "retry policy: default or naive")
	split := fs.String("split", "all", "eval only: dev, heldout or all")
	threshold := fs.Float64("t", pipeline.DefaultConfig().Threshold, "refusal threshold on normalised BM25")
	seed := fs.Uint64("seed", 1, "arrival and question-order seed")
	outPath := fs.String("out", "results/results.csv", "results file (appended)")
	qPath := fs.String("questions", "eval/questions.json", "questions file")
	data := fs.String("data", "data/parsed", "parsed papers directory")
	if err := fs.Parse(args); err != nil {
		return err
	}

	sc, ok := scenarios[*name]
	if !ok {
		return fmt.Errorf("unknown scenario %q", *name)
	}
	if *source != "stand-in" && *source != "real" {
		return fmt.Errorf("source must be stand-in or real")
	}
	if *source == "real" && !sc.real {
		return fmt.Errorf("scenario %q would spend the shared daily budget; run it on the stand-in", *name)
	}
	policy, scenarioName := traffic.DefaultPolicy(), *name
	if *policyName == "naive" {
		policy, scenarioName = traffic.NaivePolicy(), *name+"-naive"
	}

	setting, err := pipeline.SettingByName(*settingName)
	if err != nil {
		return err
	}
	docs, err := corpus.LoadDir(*data)
	if err != nil {
		return err
	}
	chunks, err := corpus.Build(docs, setting.ChunkWords, setting.Overlap)
	if err != nil {
		return err
	}
	qs, err := eval.Load(*qPath)
	if err != nil {
		return err
	}
	if err := eval.Validate(qs, docs); err != nil {
		return err
	}

	base, key := groqURL, os.Getenv("GROQ_API_KEY")
	if *source == "real" && key == "" {
		return fmt.Errorf("GROQ_API_KEY is not set")
	}
	if *source == "stand-in" {
		cfg := standin.Default()
		sc.provider(&cfg)
		cfg.Seed = *seed
		if base, err = serve(standin.New(cfg)); err != nil {
			return err
		}
		key = ""
	}

	cfg := pipeline.DefaultConfig()
	cfg.Retry, cfg.Threshold = policy, *threshold
	lim := traffic.NewLimiter(sc.limits, nil)
	adm := traffic.NewAdmission(lim, traffic.AdmissionConfig{MaxQueue: 20, Service: 1500 * time.Millisecond}, nil)
	defer adm.Close()
	p := pipeline.New(cfg, setting, chunks, llm.NewHTTP(base, key), lim, adm)

	w, err := results.Open(*outPath)
	if err != nil {
		return err
	}
	defer w.Close()

	r := loadgen.Run{Scenario: scenarioName, Source: *source, Setting: setting.Name, Patience: sc.patience}
	var rows []loadgen.Summary
	if sc.eval {
		byID := map[string]eval.Question{}
		for _, q := range qs {
			byID[q.ID] = q
		}
		r.Grade = func(id string, rep pipeline.Reply) string {
			return eval.Grade(byID[id], rep.Text, rep.Refused, rep.Cited)
		}
		// Closed loop: one question at a time, so Table 3's latencies are
		// the pipeline's, not a queue's.
		for _, q := range qs {
			if *split != "all" && q.Split != *split {
				continue
			}
			r.Jobs = []loadgen.Job{{QuestionID: q.ID, Question: q.Question}}
			s, err := r.Execute(context.Background(), p, w)
			if err != nil {
				return err
			}
			rows = append(rows, s)
		}
	} else {
		r.Jobs = jobs(sc.arrivals(*seed), qs, *seed)
		s, err := r.Execute(context.Background(), p, w)
		if err != nil {
			return err
		}
		rows = append(rows, s)
	}
	return report(out, scenarioName, rows, *outPath)
}

// jobs pairs each arrival with a question, in a seeded shuffled cycle.
func jobs(offsets []time.Duration, qs []eval.Question, seed uint64) []loadgen.Job {
	rng := rand.New(rand.NewPCG(seed, seed+1))
	order := rng.Perm(len(qs))
	out := make([]loadgen.Job, len(offsets))
	for i, off := range offsets {
		q := qs[order[i%len(qs)]]
		out[i] = loadgen.Job{Offset: off, QuestionID: q.ID, Question: q.Question}
	}
	return out
}

// serve runs the stand-in on a free local port and returns its URL.
func serve(h http.Handler) (string, error) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return "", err
	}
	go http.Serve(ln, h)
	return "http://" + ln.Addr().String(), nil
}

// report prints a one-line overview; the tables come from tables.py.
func report(out io.Writer, scenario string, sums []loadgen.Summary, path string) error {
	sent, maxLag := 0, time.Duration(0)
	for _, s := range sums {
		sent += s.Sent
		maxLag = max(maxLag, s.MaxLag)
	}
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	all, err := results.ReadAll(f)
	if err != nil {
		return err
	}
	counts := map[string]int{}
	for _, row := range all[len(all)-sent:] {
		counts[row["status"]+"/L"+row["ladder_level"]]++
	}
	keys := make([]string, 0, len(counts))
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var parts []string
	for _, k := range keys {
		parts = append(parts, fmt.Sprintf("%s=%d", k, counts[k]))
	}
	fmt.Fprintf(out, "%s: %d requests, worst start lag %dms; %s\n", scenario, sent, maxLag.Milliseconds(), strings.Join(parts, " "))
	return nil
}

package main

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"relay/internal/results"
)

func runArgs(t *testing.T, extra ...string) ([]map[string]string, string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "results.csv")
	args := append([]string{"-out", path, "-questions", "../../eval/questions.json", "-data", "../../data/parsed"}, extra...)
	var out bytes.Buffer
	if err := run(args, &out); err != nil {
		t.Fatal(err)
	}
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	rows, err := results.ReadAll(f)
	if err != nil {
		t.Fatal(err)
	}
	return rows, out.String()
}

func TestEvalOnStandInGradesEveryQuestion(t *testing.T) {
	rows, out := runArgs(t, "-scenario", "eval", "-split", "dev")
	if len(rows) != 10 {
		t.Fatalf("%d rows, want 10 dev questions", len(rows))
	}
	for _, r := range rows {
		if r["answer_grade"] == "" || r["scenario"] != "eval" || r["source"] != "stand-in" || r["retrieval_setting"] != "R2" {
			t.Errorf("row %v", r)
		}
	}
	if !strings.Contains(out, "eval: 10 requests") {
		t.Errorf("report: %s", out)
	}
}

func TestSmokeScenarioOpenLoop(t *testing.T) {
	rows, out := runArgs(t, "-scenario", "smoke", "-policy", "naive")
	if len(rows) < 3 {
		t.Fatalf("only %d rows", len(rows))
	}
	for _, r := range rows {
		if r["scenario"] != "smoke-naive" || r["answer_grade"] != "" {
			t.Errorf("row %v", r)
		}
	}
	if !strings.Contains(out, "smoke-naive:") {
		t.Errorf("report: %s", out)
	}
}

func TestRealOnlyForCheapScenarios(t *testing.T) {
	err := run([]string{"-scenario", "overload", "-source", "real"}, &bytes.Buffer{})
	if err == nil || !strings.Contains(err.Error(), "daily budget") {
		t.Errorf("overload on real Groq must be refused, got %v", err)
	}
}

func TestScenariosAreComplete(t *testing.T) {
	for _, name := range []string{"steady", "burst", "overload", "halved", "daily-exhausted"} {
		sc, ok := scenarios[name]
		if !ok || sc.arrivals == nil || sc.provider == nil || sc.patience == 0 {
			t.Errorf("scenario %q incomplete", name)
			continue
		}
		if n := len(sc.arrivals(1)); n < 5 {
			t.Errorf("%s: only %d arrivals", name, n)
		}
	}
}

